/* 令和8年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r08.committeeSessions.push(...[{"id":"r08-20260629-5","meetingId":"r08-m0708","date":"2026年6月29日","dateIso":"2026-06-29","committee":"総務委員会","time":"午前10時00分～午後２時31分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を88件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"近隣の企業にそれぞれご挨拶に行ったと思うのですが、その辺の配慮は、もうきちんとできているのでしょうか。ここを工事するのは、解体するだけでも大変だと思うし、造るのでも大変だと思うので、それだけ先に説明を求めました。","respondent":"長尾施設整備課長","answer":"今回の工事に関わる説明会につきましては、議決いただいた後、７月に近隣向けに予定をしております。一定配慮もしておりますので、その辺りを説明会でもお伝えしてご理解を得ていこうと考えております。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"太陽光は、きちんと得られるのですか。その点だけ気になったので、それだけ説明を求めました。","respondent":"長尾施設整備課長","answer":"設計の段階で太陽光パネルによる十分な発電量を確保できるところを確保しており、枚数については、 屋上で子どもたちが遊べるスペースであるとか、ほかの設備のスペースとかを考えていますので、そこまで枚数はないですけれども、発電には支障のないような計画をしております。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問・要望","question":"近隣はいくらでも高い建物を建てられると思うので、一時的に設置したとしても、恒久的にはすごく難しい。そういうことも考えられてやっていると思いますけれども、無駄にならないようにやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"辞退理由を見ると、結構、予定価格超過のためということが書かれているので、そこを確認させていただきたい。区として、公開されているのであれば、予定価格はどういう価格として、しているということなのかを伺いたいと思います。","respondent":"長尾施設整備課長、廣瀬経理課長","answer":"今、委員がおっしゃっていたものは緑化の部分になります。ソーラーパネルは塔屋の上に置く予定にしております。予定価格についてのご質問ですけれども、国や自治体の行う工事請負契約は、おおむね共通したルー ルに基づいて予定価格を積算しております。","id":"exchange-004"},{"speaker":"松本委員","kind":"質問","question":"今のソーラーパネルの質問で、須貝委員の質問で、ビルが建ったらなかなか発電できないのではないかという話がありました。五反田の公園は南東側ぐらいですか、再開発とかで周辺にビルが建っても、その辺りは考慮されて検討されたのかだけお伺いしてよろしいか尋ねました。","respondent":"長尾施設整備課長","answer":"太陽光パネルの設置場所につきましては、周辺の現状の環境は把握した上で、置く場所、置く量についても計画はしております。この敷地の中でいうと、最も高い場所で、最も太陽光が差す可能性の高いところになっておりますので、そちらのほうに設置を計画しております。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ、予定価格の中に、熱中症対策は、どこまで落とし込まれているのかということを伺いたいと思います。事故なく安全に進めていただきたいと思っているのですけれども、積算の中で、そこだけ確認をさせてほしいと求めました。","respondent":"長尾施設整備課長","answer":"熱中症対策につきましては、全ての工事の経費の中で見込んでいる状況です。ご相談いただいて、契約変更も含めて、必要な対策を講じるいうところをやっていく予定にしております。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはりこういうことはできれば避けてほしいと求めました。今回の議案に対しては賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-02","title":"第７９号議案、鈴ケ森小学校校舎改築電気設備工事請負契約","agenda":"第７９号議案、鈴ケ森小学校校舎改築電気設備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"こういうことは、経理課のほうで何か改善するという方策はないのでしょうか。それだけ少し説明を求めました。","respondent":"廣瀬経理課長","answer":"区としては、発注、積算に当たって、最新の単価、人件費等で予定価格を積算し計上するなどして、 不調にならないような対策を行っているところです。ただ、応募しやすい入札条件というところは、引き続き、区の責任として検討して対応していきたいと考えております。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"こういう入札の結果を見ると、区民の方が見たら、どうしてなのだろうという、皆さん、疑問に思ってしまうのです。嫌われているのかなと、もっと多くの企業があると思うので、ぜひ改善に向けて努力してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問","question":"今回、鈴ケ森小学校の工事は、電気設備だけなのですけれども、そういうことになった経緯、理由などを伺いたいと思います。","respondent":"荒木学校施設担当課長","answer":"定例会に契約議案を提案する予定でございましたが、こちらは、同日５月２９日の開札結果は不調となってあります。このため、本定例会におきましては、補正予算を提案した上で、今後の定例会において、 改めて契約議案を提案させていただきたいと考えています。","id":"exchange-010"},{"speaker":"のだて委員","kind":"意見","question":"今回不調になったということで、今、いろいろ工事価格、資材等上がっております。しっかり工事を進められるように、また、建設業者の方も生活が成り立つような価格として提示をしていっていってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"}]},{"id":"topic-03","title":"第８１号議案、キャビネット他の買入れ","agenda":"第８１号議案、キャビネット他の買入れ","exchanges":[{"speaker":"つる副委員長","kind":"質問","question":"５番のところに、ここに含まれているという理解でいいのか、そこだけ説明を求めました。","respondent":"石井学務課長","answer":"今、既存校舎から新校舎のほうに物品を移動する場合とか、そういったこともあります。それはまた別途、 予算で計上しています。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"品目のところで、「他」と書いてありますが、ほかに何があるのかを伺いたいのと、あと、すみません、基本的なことで、一般需用費というのはどういうものを指すのかを伺いたいと思います。","respondent":"石井学務課長","answer":"備品として登録をせねばならないような１つの単価が１０万円以上のもの、それ以外の消耗品の類いにつきましては、一般需用費で計上しています。今回は、この２つの節を併合した上で契約を行っているところです。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"ここも１の買入物品のところに、「荏原第六中学校他」と書いてありますけれども、ほかの学校も対象として入っているのでしょうか。それならば、記載されていないので、そこら辺、少し説明を求めました。","respondent":"石井学務課長","answer":"今回につきましては、老朽物品の取替えということで、荏原第六中学校のほか、戸越小学校、荏原第一中学校、山中小学校、宮前小学校、小山台小学校など、主に平成の真ん中ぐらいに購入した物品の老朽取替を対象としています。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"今回、回転釜ですとか消毒保管庫設備は、日本調理機株式会社製の機器にすることになったということで、これがいろいろ制約があったということなのですが、そこをもう少し詳しく、どのような制約があったのか、決定の経過を伺いたいと思います。","respondent":"石井学務課長","answer":"へらでつついてしまって、例えば壊れたときに保守が可能ですとか、そういったアフターメンテナンス等も含めてやっていること。ガスを使うものですので、既存のガス管にきちんと設置が可能であるですとか、こちらの物品の指定となったというようなところです。","id":"exchange-015"}]},{"id":"topic-04","title":"第７６号議案、電線共同溝等工事（特別区道Ⅰ－２４１号）委託契約","agenda":"第７６号議案、電線共同溝等工事（特別区道Ⅰ－２４１号）委託契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"ここの道路に関して、別にそんなに狭いというわけでもなし、景観がよくなるということでもなし、なぜここがこういうふうに指定されたのでしょうか。理由を説明するよう求めました。","respondent":"森道路課長","answer":"本路線につきましては、令和５年度に改定しました無電柱化推進計画の中で位置づけをしております。安全な避難を確保するということと、緊急車両がしっかりと通行できるようにということで、本路線を選定したものです。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"もう１点、そのままお尋ねします。下のほうに書いてある１３番、ここの通り、そちらも同じ理屈で無電柱化にやっていくということか尋ねました。","respondent":"森道路課長","answer":"今、昔の財務省の庁舎があったところについても拡幅の計画がございまして、そこを無電柱化を進めていく予定にしております。ですので、林試の森公園周辺を全体的に避難しやすいように設定して進めていきたいと思います。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"今回は随意契約ということでやられていますけれども、随意契約にした理由を伺いたいと思います。","respondent":"森道路課長","answer":"電線共同溝整備というのは電柱を取り扱うもので、ＮＴＴあるいは東京電力しか、なかなか実際問題として工事に携われないところがあります。","id":"exchange-018"}]},{"id":"topic-05","title":"第７７号議案、東大井公園改修工事請負契約","agenda":"第７７号議案、東大井公園改修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"私は全部見ていないので、図面は分からないのですが、ここもそういう対応をされるのでしょうか。説明を求めました。","respondent":"大友公園課長","answer":"新たに整備する防災施設といたしましては、下水道直結のマンホールトイレ、また、かまどベンチを設置する予定です。こちらにつきましては、既に１００トンの防火貯水槽が整備されているということで、井戸・防火貯水槽の設置予定はございません。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"よく聞こえなかったのですけれども、井戸は設置されないということか尋ねました。","respondent":"大友公園課長","answer":"ここの公園については井戸は設置はしません。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"それに対して、やはりきちんと対応すべきだと思うし、やっていかなくてはいけない。区民の生命、これからそういう対応をしていくような考えはおありなのでしょうか、説明を求めました。","respondent":"大友公園課長","answer":"井戸の設置につきましてですけれども、既存の公園も含めて、災害時に活用できる井戸の整備を今年度の事業から新たに進めているところです。公園を新たに設置する際とか、既存の公園につきましても、井戸の確保に視点は重きを置いて整備を進めていきたいと考えているところです。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"どういうものなのかということと、ミスト施設も２基設置されるということで、どういうところに設置しているのか。今回設置するとなった経緯ですとか、ミスト施設を設置する基準とか考え方があったら伺いたいと思います。","respondent":"大友公園課長","answer":"ミストについてですけれども、ミストの設置は全体の方針での考えは、現時点でのお示しはございません。そういうような意見を踏まえて設置する施設を選定した中にミストが入っているところです。","id":"exchange-022"},{"speaker":"つる副委員長","kind":"質問・要望","question":"十分な移動その公園に横づけをして、乗り降りも含めてやれるようなところまで、整備していただきたい。ほかの所管等々を含めて、イメージしながら、ここにインクルーシブ遊具というか、そういう公園となっていくかどうかというところを説明するよう求めました。","respondent":"大友公園課長","answer":"今回、インクルーシブの導入の背景からご説明させていただきたいと思います。目の前の道路につきましては、一定少し広くなるというところもありますので、一定の配慮がされているというところで考えたところです。","id":"exchange-023"},{"speaker":"石田（秀）委員長","kind":"質問","question":"私も第１回定例会で質問をさせていただいた井戸の件なのだけれども、２００ｍで１８０か所だったか、それぐらい必要だと思っていますと質問しました。ですから、非常にそういう意味では、やっていただいているのだなと思ったのです。","respondent":"大友公園課長","answer":"今年度から全体の区の中の井戸を考えていくということで、場所の選定とか、そういうような必要性というところも踏まえ検討しているところです。その中の一環として、多分、町会、今どこにあるのかという調査をさせていただいているという流れになっているかと思っています。","id":"exchange-024"}]},{"id":"topic-06","title":"第７８号議案、西大井広場公園（北側）改修等工事請負契約","agenda":"第７８号議案、西大井広場公園（北側）改修等工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"ここの場所は、多くの木が、中木ですか、たくさんあると思うのですが、そこはほとんど伐採するのですか。かなり緑が多い場所だと思うのですが、その辺について説明を求めました。","respondent":"大友公園課長","answer":"その理由といたしましてですけれども、既存の園内、勾配が大きく駐輪場を整備する観点からも、勾配をならすため、大幅な切土を実施します。その結果、ほとんど樹木は、基本的には伐採するという形なのですけれども、新たに新しい樹木という形で新植をします。","id":"exchange-025"},{"speaker":"須貝委員","kind":"質問・要望","question":"できるだけ残してほしいと思うのですけれども、１回伐採して、非常に残念です。近隣の皆さんの、ここに住まわれている西大井の皆さんの緑に対する思いもあると思うので、その辺もいろいろ含んで対応してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"こしば委員","kind":"質問・要望","question":"スケジュールについて教えてほしいと求めました。今回議案に上がっている駐輪場を建設して、そこから３階建てのほうを建て直していくのかどうか、その辺りを教えてほしいと求めました。","respondent":"大友公園課長","answer":"本件、現在、契約手続等々をこのようにお伝えして進めているところではありますけれども、建屋の駐輪場も、別途、改修工事を実施する予定です。令和９年２月頃、約１か月間程度は、建屋の影響の仮設の駐輪場というようなところも踏まえて整備を進めていくという考えです。","id":"exchange-027"},{"speaker":"こしば委員","kind":"確認","question":"確認ですけれども、仮設でここの公園に２００台のという答弁と認識してしまってよろしいですか。あくまでも仮設での対応という認識でいいか尋ねました。","respondent":"大友公園課長","answer":"建屋の工事で駐輪場が使えなくなるというところを踏まえての駐輪場は、一時的な仮設という形のものにはなります。","id":"exchange-028"},{"speaker":"松永委員","kind":"質問","question":"整備内容のところなのですけれども、トイレについてですが、こちらは、今、ステンレス製の１人用の和式の便所があると思うのですけれども、こちらは全部取っ払って、また新しい誰でもトイレのような形になるのか、その辺を伺いたいと思います。","respondent":"大友公園課長","answer":"その新設内容が、男性用のトイレとして、大便器、小便器、あと女性用トイレとして、洋式が１つ。バリアフリートイレを１基という形で設けることで計画をしています。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"確認なのですけれども、今回の１８１台の普通自転車と大型２０台の駐輪場が仮設ということなのか、そこを確認させてほしいと求めました。住民の皆さんにも親しまれてきた場所だと思うので、近隣の住民との合意というか、調整はどうなっているのか伺いたいと思います。","respondent":"大友公園課長","answer":"中木が１１２本になる予定です。プラス、今いろいろなご意見、落ち葉が来ないように配慮してもらいたいということを踏まえて配置等々を計画しているところであります。","id":"exchange-030"},{"speaker":"のだて委員","kind":"意見","question":"高木が９０本、移設が１６本ありますけれども、しっかり説明してほしいと求めました。住民の納得を得ていただければなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"つる副委員長","kind":"確認","question":"今年度策定予定のシェードポリシーを１年前にやっているという、ミストがあって、涼しさは確保されるのかなと思います。それに耐え得るような今の状況になっているのかどうかを、東屋とか、この日陰というところや緑園というところでの考え方を確認したいと求めました。","respondent":"大友公園課長","answer":"この１０２本、木陰確保ができ、緑道を散策する上で木陰の中を楽しんで散策をいただけるような計画になるのかなと考えています。配置、また、１年を通して散策を木陰の中で楽しんでいただけるような公園になるというところで計画をしています。","id":"exchange-032"}]},{"id":"topic-07","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"すみません、この変更内容ですが、今回、インフレスライドに対する契約が変更された額と、それから廃棄物運搬処分の変更に対する額を、大まかでいいから説明を求めました。","respondent":"大友公園課長","answer":"インフレスライド分として約７１０万円、廃棄物運搬処分の変更といたしまして約１８０万円のそれぞれ増となっているところです。","id":"exchange-033"},{"speaker":"中塚委員","kind":"意見","question":"変更内容の２つ目の廃棄物運搬処分の変更ということですけれども、廃棄物とは何なのか、自然由来のものなのか、それとも掘っているときに何か人工物があったのか、この廃棄物は何かご説明ほしいと求めました。","respondent":"大友公園課長","answer":"古い目黒川の護岸構造物や、考えられるところはあるかと思うのですけれども、どのような使われ方をしたコンクリート殻だったかは不明です。コンクリート殻という形になります。","id":"exchange-034"},{"speaker":"中塚委員","kind":"意見","question":"どういう状態、もう遡れないのかなとも思うものの、少しやはり釈然としないというのが正直な気持ちです。もう少し区として何か努力ができなかったのか、した結果、不明ということなのか、もう少し詳しくご説明いただけたらと思いますとの意見を述べました。","respondent":"大友公園課長","answer":"やはり古い年代のものというところもあり、調査した結果というところで、調査する前は本当に何も分からないコンクリート殻だったのですけれども、いろいろな目黒川の護岸の構造がここまで来ていたのではないかとか、様々な調査をした結果、やはり不明というところが結果です。","id":"exchange-035"},{"speaker":"須貝委員","kind":"質問","question":"やはり適当な場所がなかったことと、今急いで造らなければいけないということで、このような場所を選定したのでしょうか。このような、私から思うと歪な建物だと思うのですけれども、そういうことで進めたのか尋ねました。","respondent":"立木品川区清掃事務所長","answer":"児童相談所の整備にあわせまして、子供の森公園に少し変更がございました。車両の出入りもありますので、道路に面したこの位置にという形で移転という形になったという経緯です。","id":"exchange-036"},{"speaker":"須貝委員","kind":"質問","question":"もう１点だけ。ほかの車両が目の前の道路を本当にたくさん通って、かえって危ないような気もするのですが、その辺は大丈夫なのか尋ねました。","respondent":"立木品川区清掃事務所長","answer":"交通の流れを見ながら安全に出庫させるという形でやっておりますので、新しい分室になりましても、安全上配慮して続けてまいりたいと思います。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"ここは隣に子供の森公園がありますので、子どもたちの出入りもあると思います。工事の安全性をしっかり確保してほしいと思うのですけれども、その辺りを伺いたいと思います。","respondent":"長尾施設整備課長","answer":"今回の新築工事に当たりましては、当然、安全管理には十分配慮して、公園の利用にも支障がないように努めてまいりたいと思います。","id":"exchange-038"}]},{"id":"topic-08","title":"第６０号議案、品川区特別区税条例の一部を改正する条例","agenda":"第６０号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"令和３１年度以後もずっとやられるということで、１０年間延長されてしまうということで、区の見解を伺いたいと思います。全体的に、区民にとってはどういう影響があるのかというところを各項目で伺いたいと思います。","respondent":"初貝税務課長","answer":"２０５万円以下の方に関しましては、住民税は、提出がないと課税になる可能性があるというところで対応するものです。（６）に関しましても、ここ３年、区に対しての影響はないかと考えています。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"なぜ義務化するのかということで、なぜなのかなということがあるので、もう少し詳しく説明いただけるところがあれば伺いたいと思います。差をつけているということで、なぜ差をつけるのかということがよく分からなかったので、もう少し説明いただけることがあれば伺いたいと思います。","respondent":"初貝税務課長","answer":"（２）の公的年金などの受給者に関する義務ですけれども、こちらは少し説明が重複してしまいますけれども、我々が賦課していくというものです。その先に関しましては、先ほど少しご説明したように、今までの経緯等々を踏まえてなされていると。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"これは誰に聞いたらいいのかよく分かりませんけれども、ｉＰａｄは手で拡大できるではないですか。特にこういう小さい字は拡大しないと見えないので、少し工夫していただきたいと思うのですけれども、その２点、伺いたいと思います。","respondent":"初貝税務課長","answer":"１点目のところですけれども、区としては、その内容等々に関して判断する立場にはないと考えております。資料上の工夫でありましたり、解像度等々は、また関係所管と調整をしていきたいと考えています。","id":"exchange-041"},{"speaker":"中塚委員","kind":"意見","question":"なのに、この税制改正になると、国によって判断すべきもので、区が示すものではないと、 この姿勢は明らかな矛盾だと思います。恒久平和に対して、区自らが姿勢を示すべきときに、こういう品川区の姿勢は改めるべきだと指摘しておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"須貝委員","kind":"質問","question":"これは、メリットとして、自治体が寄附を受けやすいような仕組みに変わるということなのでしょうか。最初の１点だけ、その辺、ご見解を説明するよう求めました。","respondent":"初貝税務課長","answer":"（１）の公益信託の見直しに伴う所得税の改正に関してです。皆さん、控除はできますよ、そういうような制度です。","id":"exchange-043"},{"speaker":"須貝委員","kind":"意見","question":"なかなか今回、字は拡大すれば大きくはなるのだろうけれども、非常に分かりにくい制度だったと思うので、こういうときはぜひ企画経営部長が皆さんにより分かりやすいようにお伝えしてくれると、 我々も安心して審査できるのではないかと思いましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"つる副委員長","kind":"質問","question":"既存の ２.１％の中で、復興債を発行して、復興事業そのものが後れたりとかという認識ではないのかなというふうに国の取組として理解をしている。１％をそういうふうに変えるわけですから、主でなおかつ１０年延長でという、もしお分かりになれば参考までに説明を求めました。","respondent":"初貝税務課長","answer":"そうですね、今ご指摘いただきました償還等々の話です。手元になくてお答えできないのですけれども、いずれにしても、国のほうでしっかりと議論されているものと認識しております。","id":"exchange-045"},{"speaker":"のだて委員","kind":"意見","question":"しかし、 防衛特別所得税の軍事費拡大の原資にするため、どんどん拡大していけば戦争に近づいていくことにもなります。今回の改正は、それを具体化するものですので、反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"中塚委員","kind":"意見","question":"もう一言、やはり東日本大震災の復興の財源を使って軍事費の増税をする、このことに品川区は反対をすべきだと思います。国の議論に委ねるというその姿勢は、とても品川区民の理解を得られないと改めて指摘しておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"}]},{"id":"topic-09","title":"第６１号議案、品川区附属機関の構成員の報酬および費用弁償に関する条例の一部を改 正する条例","agenda":"第６１号議案、品川区附属機関の構成員の報酬および費用弁償に関する条例の一部を改 正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今、いじめ対策委員会が実際に調査などをしている件数は何件なのか伺いたいと思います。今回、委員長が３万円、委員が２万３,０００円ということで、この金額設定にした理由があれば伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"令和７年度は１３件あったということですので、順次、やはり常に複数件数を抱えてやっていらっしゃるということだと思います。そういったところもありますので、今回、そうしたことも加味した設定になっているのかというところを最後に確認させてほしいと求めました。","respondent":"中西総務課長","answer":"委員ご指摘のとおり、確かにガイドラインに書かれております３つの類型等々あります。そういった部分を含めて報酬を設定しているものです。","id":"exchange-049"},{"speaker":"中塚委員","kind":"意見","question":"増額ということなので、賛成をしたいと思いますが、担っている職責を率直に思うと、もっと引き上げてもいいという議論が起きるべきだと私は思います。もっと引き続き、弁護士の方々と意見も聞きながら、今後、 議論を進めていただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"}]},{"id":"topic-10","title":"令和８年陳情第２７号、税法上の障害者控除を、「要介 護２」認知症の者にも適用するよう求める陳情","agenda":"令和８年陳情第２７号、税法上の障害者控除を、「要介 護２」認知症の者にも適用するよう求める陳情","exchanges":[{"speaker":"こしば委員","kind":"質問・要望","question":"確認をさせていただきたいのですけれども、冒頭で何か所か分からないところがありました。先ほど、法的根拠があって独自にできないような話をされていたような気がしたのですけれども、その辺りをもう一度教えてもらっていいか尋ねました。","respondent":"初貝税務課長","answer":"先ほどの説明と少し重複してしまう部分はあるかと思いますけれども、高齢者福祉課長のほうから説明がありました障害者控除対象者認定書を受けている方に関しましては、そちらの認定を受けていれば障害者控除の適用の範囲内になるというような構図になっております。","id":"exchange-051"},{"speaker":"こしば委員","kind":"質問","question":"そうすると、結局、自治体の判断に委ねるところが多いという認識でよろしいか尋ねました。","respondent":"初貝税務課長","answer":"そうですね、いわゆる認定書を受ける対象の範囲に関しては、市区町村のところで定めているというか、認められている部分です。要は、それ自体を障害者控除の対象の範囲として拡大することは各自治体には認められていない、そういったことになっております。","id":"exchange-052"},{"speaker":"こしば委員","kind":"質問","question":"この陳情にあるとおり、要介護２の方を対象とした場合の税額控除、おおよそどのくらいのものと見積もりをされているのか教えてほしいと求めました。","respondent":"初貝税務課長","answer":"２６万円の所得係数がかかる、要介護２の方が、２,４００人弱程度というところ。税金、区政という意味では、約１,９００万円程度の税収が減収というような形になるということです。","id":"exchange-053"},{"speaker":"こしば委員","kind":"質問","question":"その辺り、必ずしも例えば、認知レベルと、多分、要介護が進むイコール認知症が進んでいくとは、 それはイコールの関係ではないわけではないですか。先ほど、幅広く考えていきたいという話がありましたけれども、認知症との関連性のようなものを教えてほしいと求めました。","respondent":"佐藤高齢者福祉課長","answer":"要介護度と認知症の関係のご質問かと思いますので、私のほうからお答えいたします。冒頭ご説明したとおりでして、そういったところを詳細にこれから検討いたしまして、関係課と調整した上で検討していきたいと考えております。","id":"exchange-054"},{"speaker":"こしば委員","kind":"質問・要望","question":"要介護だけでなく、また認知症のレベルを、そういうものを、今、複合的に全体観をもって検討されているということですので、ぜひそれは進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"中塚委員","kind":"質問","question":"区も追いつかなければということなのか、基準を見直す必要があると、その必要の理由をしっかりと伺いたいと思います。いつからの実施を目指しているのか、対象はどこまで広げようと思っているのか、現状のお考えを伺いたいと思います。","respondent":"佐藤高齢者福祉課長","answer":"品川区が要介護３以上と置いているところが、周辺自治体と比べてどうなのかというところは、課題があると認識しているところです。もう１点、繰り返しになりますけれども、関係課と調整する中で決定していきたいと考えております。","id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区の要介護３以上という要介護の区分だけで見るのは、なかなか実態を反映し切れていないのではないかと、そういうことでよいのか改めて伺います。来年度予算に反映していただきたいということと、要支援以上を対象とするというふうにしてほしいと求めましたが、最後にいかがか尋ねました。","respondent":"佐藤高齢者福祉課長","answer":"毎年事務事業評価等を通じて、その時点でどうなのかというところは、これまでも検討してきたところです。見直しの時期につきましては、繰り返しにはなってしまいますけれども、その範囲も含めて、 関係課と調整したいと考えております。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"障害者控除の現状とかが分かるようにしていただきたい、これは今後お願いしたいと思います。現状を伺いたいのですけれども、人数をそれぞれ伺いたいのと、ここ３年の普通障害者控除と特別障害者控除の認定数をそれぞれ伺います。","respondent":"佐藤高齢者福祉課長、初貝税務課長","answer":"合計１６２件で、障害者が５１件、特別障害者は１１１件です。例年、この程度の数で推移しているという認識です。 障害者控除に係る人数ですけれども、一般障害者控除を受けられている方の合計が、おおよそ令和７年度分の数字になりますけれども、一般のほうが約３,６００人、特別障害のほうが約 ２,４００名程度です。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"対象になる方にはぜひお知らせをしていただきたい、申請書などを送ってほしいと求めましたが、それを１点伺いたいと思います。分かれば、２３区の中で要介護２以下を対象にしている区がどれだけあるのかを伺えればと思います。","respondent":"佐藤高齢者福祉課長","answer":"要支援の方、あるいは、そういった自立度のここから認定しますという基準を公表していない自治体もあります。現在の品川区のように、要介護度で認定するという自治体もございまして、様々な形で基準を置いているというのが現状です。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"厚労省の通知の中でも、こうしたところを利用してやっている自治体も多くありますので、ぜひ要支援も含めて拡大していってほしいと求めました。取り替えに３０万円以上の出費が出てしまったということから見ても、ぜひ広く利用できるように、対象も拡大していっていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"松本委員","kind":"意見","question":"一応読み上げるならば、その障害の程度が第１号または第３号に掲げる者に準ずるものとして市町村長等が認定をしている人となっているかと思います。","respondent":"佐藤高齢者福祉課長","answer":"我々として、要介護度をどこに置くのかというところで、要介護３ではないかということもあります。介護保険自体が自立支援を１つの目的としている関係がありまして、その後、区としては設定していくというふうに考えております。","id":"exchange-061"},{"speaker":"須貝委員","kind":"質問","question":"そういう方向で進んでいくと、こういうふうにお願いされていることに関しては、そのとおりだというふうな考え方で我々は受け止めていいのでしょうか。説明を求めました。","respondent":"佐藤高齢者福祉課長","answer":"現在の要介護３から拡大していくということをこれから検討していくというところで、税務課長からの説明もありましたとおりで、そういった方向で進めていきたいと考えています。","id":"exchange-062"},{"speaker":"つる副委員長","kind":"質問・要望","question":"各委員の質疑を伺って分かったことで、確認をさせていただきたいところがあって、そこをまず教えていただきたいことが１つ。現状、この障害者対象認定書に基づいて、認定書が交付されていて控除を受けていらっしゃる方の人数についても分かったら説明を求めました。","respondent":"初貝税務課長","answer":"今、委員ご指摘の、それぞれ認定のところですけれども、一般と障害の中に、認定書をもって障害者控除を受けている方が、どれくらいかということで、大体おおよそなのですけれども、４０から５０名程度の方が認定書をもって障害者控除を受けているというようなところです。","id":"exchange-063"},{"speaker":"つる副委員長","kind":"質問・要望","question":"ざっくり２,４００人、いわゆる区の立ち位置で見たときの影響という表現が適切かどうかは別にしても、これは理解しました。要介護２、ほかの区の状況ですとか、冒頭の説明を伺っていて思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"松永委員","kind":"確認","question":"まず、東京２３区の大部分の自治体が既に認知症の実態を考慮して、要介護２以下の方にも適用しているということを確認できました。そうしたことも踏まえて、この陳情の趣旨については賛同し、今回、趣旨採択という形にさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"つる副委員長","kind":"確認","question":"先ほど質疑の中でも確認させていただきました。要介護２で認知症ということで明記されていたかと思いますけれども、冒頭の説明を含めたその他の質疑を含めて、趣旨採択という形にしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"のだて委員","kind":"意見","question":"控除を受けられる障害者と同程度の状況の高齢者の方がいるのに控除を受けられないというのは不公平だと思います。議会からもぜひ後押しして進めていきたいと思いますので、採択していきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"松本委員","kind":"意見","question":"これだけ、１点、今回の話を見ていて思うのですけれども、税法上は、かなり市区町村長に裁量があるような規定に施行令でなっている。自治体の対応なのだというところがはあるものであれば、適宜見直しをして、趣旨採択と申し上げしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"須貝委員","kind":"意見","question":"弱者を生まない品川区政、このような適用は見直す時期に来ているかと思います。この適用を早く改善して、そして、本当に温かい福祉に強い品川区になってほしいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問・要望","question":"一刻も早く実施してほしいし、対象も広げてほしいと思うので、後発組が要介護２で終わってはいけないと思うのです。ぜひ要支援以上にしていただきたいという思いから、趣旨採択とさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"のだて委員","kind":"質問・要望","question":"私は採択として進めてほしいと求めましたが、皆さん、もし全会一致で趣旨採択できるのであれば、そのほうが区民の皆さんにも歓迎されると思いますので、趣旨採択に合わせるかたちでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"須貝委員","kind":"意見","question":"私も同様で、本来は採択でお願いしたいところですが、皆さん、全会一致となるならば、趣旨採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"}]},{"id":"topic-11","title":"令和８年陳情第１５号 昇降機が最新基準（平成２１年・２６年告示）に適合していな い旨のシールを乗り場および籠内に掲示することを求める陳情","agenda":"令和８年陳情第１５号 昇降機が最新基準（平成２１年・２６年告示）に適合していな い旨のシールを乗り場および籠内に掲示することを求める陳情","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"議会棟がどうなのかということも含めて、この安全シールを貼っていないエレベーターは何台か、どこかということをまず１点伺いたいと思います。適合していない旨のシールを貼るということが、災害対策としてどうなのか、考えも伺いたいと思います。","respondent":"長尾施設整備課長","answer":"ご説明しました地震時管制運転装置に関して、戸開走行保護装置、それぞれ国交省が任意の表示制度としてシールを貼れるような制度を準備しております。","id":"exchange-073"},{"speaker":"中塚委員","kind":"質問","question":"知りたいという方がいるのは事実ですから、そちらを強めていくことが、やはり必要な対応かなというふうに改めて思いました。問合せがあった際には丁寧な説明は必要だと思いますけれども、特に震災時の対応という意味での基本的な私の思いは、今述べたとおりです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"のだて委員","kind":"質問・要望","question":"その上で現状の確認なのですけれども、区の施設で、このリスト以外にも既存不適格が約１０基あるということでよいのか伺いたいと思います。いつまでにこの既存不適格を解消しようとか、１年に何基解消しようとか、そういう計画とか更新はあるのか伺いたいと思います。","respondent":"長尾施設整備課長","answer":"それが１つ大きな課題であると感じておりまして、なかなか思うように順番どおりに進んでいくという確保が難しいような状況もあります。どういった時期に工事が行えるかというところを具体的に詰めていくというところを今後もやっていきたいと考えております。","id":"exchange-075"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、適合しているものは基本的にシールが貼ってあるということなのかを確認させていただきたいのと、議会棟のところはシールは貼っていないですよね。区役所本庁舎のところは、適合していてもシールが貼っていないものがあるのかなと思ったのですが、その理由があれば伺いたいと思います。","respondent":"長尾施設整備課長","answer":"エレベーターメーカーの状況につきましては、委員おっしゃるように、技術者不足といったところは１つ大きな要因になっているかと思います。すみません、個別の状況についてまでは全部把握していませんので、確認したいと思います。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問・要望","question":"まずは改修をしっかり進めてほしいと求めましたし、できるだけ早く設置をしていくことが必要だと思いますので、これは求めておきたいと思います。シールのほうは確認していただいて、しっかりやはり区民に分かるように知らせていくということが私は必要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"須貝委員","kind":"意見","question":"日本全国でも１００万台のエレベーターが、品川区としても、少しずつでも改善するために対応してほしいと思います。意見だけで終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"松永委員","kind":"意見","question":"対象となる既存不適格の昇降機については、もう１つは、国のマーク表示制度も自主的な改修を促進するための任意制度であることは分かります。利用者や高齢者、かえって冷静な判断ができないのではないかというおそれがあるため、この陳情に関しましては不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-079"},{"speaker":"こしば委員","kind":"質問・要望","question":"既存不適格であったとしても、直ちにそこに違法性があるわけではなく、改修しなければならないという法的な義務が課されているわけではありません。不安に陥ってしまう、そういった危険性があると思いますので、本陳情に関しては不採択とさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"つる副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。質疑を確認させていただいて、冒頭の説明も含め、優先順位をしっかりとつけて適格にしていくことをしっかりと進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、趣旨採択です。やはり分かりやすく区民に伝えていくことが必要だと思いますので、趣旨採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-082"},{"speaker":"松本委員","kind":"意見","question":"本件については、シール云々というよりも、エレベーターが既存不適格をどう解消していくかということが大事だと考えております。今回の既存不適格ということのシールを貼っていくよりも、区民の安全に資すると考えておりますので、シールについては不採択と申し上げしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"中塚委員","kind":"質問・要望","question":"適合していない旨のシールを貼るというよりも、設備の改修をしっかり進めていくということが基本的なスタンスだと思います。更新には３０年かかるという話がありましたけれども、３０年と言わずに、慎重に検討していくという姿勢は求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"}]},{"id":"topic-12","title":"令和７年度品川区一般会計予算繰越明許費繰越計算書","agenda":"令和７年度品川区一般会計予算繰越明許費繰越計算書","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"少し変なことを聞きます。なぜこのタイミングなのかということがよく分からなかったので、不勉強ですみませんけれども、説明を求めました。","respondent":"加島財政課長","answer":"今回の繰越明許費の報告につきましては、地方自治法施行令第１４６条第２項に基づきまして、議会に報告を行うことになっているものです。そのため財政を所管しております総務委員会にご報告をしています。","id":"exchange-085"}]},{"id":"topic-13","title":"審査請求の却下の報告について（報告第２１号）","agenda":"審査請求の却下の報告について（報告第２１号）","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"なるほどと思いながら聞いたのですけれども、どのような審査請求があったのかということは聞いてはいけないのか、言えないのか。それはそれで示していただきたいのだけれども、聞いてはまずいのですか、そこも含めてご説明いただけたらと思います。","respondent":"中西総務課長","answer":"恐れ入ります、冒頭で申し上げればよろしかったのですが、今回の案件、相手先の方が特定されないようにといった形で、少し分かりづらいご説明をしているといったところでご理解いただければと思います。","id":"exchange-086"},{"speaker":"中塚委員","kind":"質問","question":"特定されてしまうのですか。何のことだか全然分からないですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"松本委員","kind":"質問","question":"令和８年、今年の５月に公益通報で調査した結果、いかがでしょうか。ご用意がなければ、また明日、ご用意していただいてということでもよろしいかと。","respondent":"中西総務課長","answer":"恐れ入ります、委員長とご相談しまして、どのような取扱いにするか検討させていただきたいと思います。","id":"exchange-088"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.29so.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":60,"characters":61635,"voices":379}},{"id":"r08-20260630-6","meetingId":"r08-m0708","date":"2026年6月30日","dateIso":"2026-06-30","committee":"区民委員会","time":"午前10時00分～午前11時51分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.30ku.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":3,"characters":510,"voices":5}},{"id":"r08-20260630-7","meetingId":"r08-m0708","date":"2026年6月30日","dateIso":"2026-06-30","committee":"厚生委員会","time":"午前10時00分～午後２時13分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"令和７年度品川区障害福祉計画等実績","agenda":"令和７年度品川区障害福祉計画等実績","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"しながわの福祉を見ると３３か所で３４０人分ですが、これが実際に今何か所で何人分あるのか、児童発達支援と両方併せて伺いたいと思います。そういうことに対して、どのように増やしてくのか区としての方針があるのか、児童発達支援と併せて伺えたらと思います。","respondent":"石橋障害者施策推進課長","answer":"しっかりと活用していただくように、開設相談等も、説明をこちらで事業者にやっていければとは考えています。まだまだ数が足りない認識はありますので、そういったところ、児童発達支援と放課後等デイサービスの整備に努めてまいりたいと考えております。","id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"自宅に戻ったということになるとしたら、 地域生活移行は親の元に戻るということになったのか、具体的に伺いたいのが１点です。令和６年度の１つのくくりの一番下に、ここにかもめ会の代表の方もぜひ入れて会議をやってほしいと、その連絡協議会のメンバーについても伺います。","respondent":"石橋障害者施策推進課長","answer":"アパートなどの独り暮らしという認識はしていますが、それに対して地域移行ができるようにサポー トしていくということで進めております。メンバー全員を今把握はしていないのですが、今、委員がおっしゃられた方については出席をされていると認識をしております。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"そこの実績はどういう状況になっているのか伺いたいのと、移動支援ですが、今回またかなり手厚い品川区の支援がされることになったと思うのです。そのことによってどのように改善されていくのかを伺えたらと思います。","respondent":"石橋障害者施策推進課長、芝野障害者支援課長","answer":"１点、答弁が漏れておりました。地域精神保健福祉連絡協議会の回数について、令和７年度は１回開催しております。 令和８年度から支援体制を強化しまして、９５事業所、もう１００事業所近くになってきております。待遇は大分改善されておりますので、利用者が一定程度増えても、それを受け入れられる体制を今後つくっていきたいと考えております。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"意見","question":"医療的ケア者のショートステイはぜひお願いしておきたいと思います。今、品川区でもそういう、人工呼吸器をつけた方もぜひ受け入れていただけるように交渉もお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"吉田委員","kind":"確認","question":"ご本人のご希望はもちろんですが、地域移行として区が評価するのは、やはり課長が今おっしゃったとおりグループホームとか独り暮らしを始める。きちんと区が本来目指している地域移行なのかを確認すべきだと思うのですが、その点についてぜひ伺いたいのですが、いかがでしょう。","respondent":"石橋障害者施策推進課長","answer":"そういったところも、今年度、また推進委員会もありますし自立支援協議会もあります。それぞれに自立支援協議会でも部会も設置しておりますので、活用しながら、施策についてもしっかりと支援を充実していきたいと考えております。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひその辺はきっちり、こういう計画の中でも目標を立てて進めてほしいと求めました。ぜひ、本当に今進んできているという前提でさらに進めていただきたいと思うのですが、その点についていかがか尋ねました。","respondent":"石橋障害者施策推進課長","answer":"現実であり、一人一人の方にどう声をかけて入っていただくかは、正直なかなか難しいところではあります。そのご家族や団体のお声などは、昨年度よりもより一層しっかりと聞いて、反映してまいりたいと考えております。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"本当に団体に参加していない方たちも参加できるような仕組みもできると思うので、その辺についてはぜひ検討してほしいと求めました。私たちが要求しないだけなのか、傍聴したいですと言ったらできるのか、できないという思い込みでお願いもしないのですが。","respondent":"芝野障害者支援課長","answer":"自立支援協議会本会ではなくて専門部会ですが、今のところは非公開という形でやらせていただいております。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"議員だけではないですから、何かそういう方もいらっしゃると思いますので、ぜひ傍聴ぐらいはさせていただいてもいいと思うのです。今検討中とか、そういうことがあったら教えていただきたいのですが、いかがか尋ねました。","respondent":"芝野障害者支援課長","answer":"専門部会の公開につきましては、まだ内部的には検討はしておりませんので、今後、その在り方も含めて研究してまいりたいと思います。","id":"exchange-008"},{"speaker":"吉田委員","kind":"意見","question":"その辺については、今ホームページに自立支援協議会などはきちんと出てきますので、ぜひそういうことも検討の中に入れていただければいいと思います。傍聴も、団体の方だけでない障害者の関係の方も、ぜひ研究ではなくて前向きに検討していただけたらいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"やなぎさわ委員","kind":"質問","question":"絆ホールディングスという事業所が、就労継続支援Ａ型の加算を利用して、８０億円以上の加算を詐取していた事件がありました。６か月以上の定着などを含めて、もしくは今後する予定があるのか、お伺いしたいと思います。","respondent":"芝野障害者支援課長","answer":"就労支援における就労後のモニタリング支援のお問合せだと思うのですが、離職支援を行っておりまして、適切なアドバイスをしています。","id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"質問","question":"数字を出す上で、今後そういったものも入れて追跡し、数字も入れておく必要がある。それこそ健全性の担保という意味で思うのですけれども、そういったお考えがあるかをお伺いしたいです。","respondent":"石橋障害者施策推進課長","answer":"今お話がありました就労継続支援のＡ型、Ｂ型に関しましては、区の指導検査の対象事業にはなっておりますので、区で指導検査に入ることで、サービスの質の一定の水準を図っていただくというところは、しっかりと区としても見ていきたいと思ってあります。","id":"exchange-011"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ちなみに、昨今、就労支援で絆ホールディングスの件があったり、食材費の件でも不正の案件があったりしたと思うのですが、そういった何か点検は、最近、品川区ではされていらっしゃるのか尋ねました。","respondent":"石橋障害者施策推進課長","answer":"申し訳ありません。運営指導の詳細については今把握をしていないので、そういった今、委員ご指摘の部分の指導に入ったかは、把握していないところになります。","id":"exchange-012"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"もちろんほとんどの事業所はしっかりと健全に運営していると思うのですが、やはり一部のそういった事業所があることもまた事実ではあると思います。伴走をしていただきたいというのと、もしくは定着後の伴走、そういったものもぜひ数字として出していただくことも要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"１番目の地域移行で、そこの新しく地域移行等意向確認担当者という役割ができて、確認をさせてほしいと求めました。確認をさせていただいて、これもこの３５％という数字をどのように認識されているか、最後に説明を求めました。","respondent":"石橋障害者施策推進課長、芝野障害者支援課長","answer":"私からは、住まいの確保についてと、定着支援事業所の定着率の３５％の認識というところの答弁をします。定着率の３５％をどう認識しているかは、目標値２５％以上が、一定程度評価ができるものと考えています。地域定着支援の実績ゼロですが、区内に定着支援をやっている事業所はございませんが、２４時間の見守りも含めて対応しておりますので。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問","question":"そうすると、地域定着支援が実績ゼロだけれども、障害者地域生活サポート２４で代替している、代わりになっているという意味で、そうすると実質的に、地域定着支援事業としてはゼロだけれども、障害者地域生活サポート２４で何件それをカバーしていると、そういう言い方になるのか尋ねました。","respondent":"芝野障害者支援課長","answer":"障害者地域生活サポート２４事業の実績ですが、当初登録者数としては、令和７年度に知的障害者３０人、精神障害者６０人がいまして、支援の延べ件数になりますが、知的障害者が１,１８０回、 精神障害者が２,６５６回、こちらでカバーさせていただいているところです。","id":"exchange-015"}]},{"id":"topic-02","title":"令和７年度品川区介護保険制度の運営状況","agenda":"令和７年度品川区介護保険制度の運営状況","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"特別養護老人ホームに入れるかどうかということも変わってくるので、ぜひ見直していただきたいので、伺います。６,２７７件を在宅介護支援で立てているわけですが、これは要望ですが、教えていただけたらと思います。","respondent":"佐藤高齢者福祉課長","answer":"この要支援２と要介護１は、状態が不安定ですとか、それ以外ですと要支援２という振り分けになっております。要介護認定の有効期限は最長３年になりますので、３年程度で全体の要介護度がこの基準に沿って変わっていくとご認識いただければと考えております。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それにもかかわらずなぜ介護保険料だけが高いのか、私は少し不思議だと思っていまして、区としてどう考えるかを伺いたいと思います。４億円ぐらい少なくなっているのですが、なぜこれだけ地域支援事業が減ったのか、その理由が分かったら教えていただけたらと思います。","respondent":"佐藤高齢者福祉課長、樺島高齢者地域支援課長","answer":"その中で今後、来年度以降３年間の事業期間での給付費見込みを出しまして、それに基づいて算定してまいります。こちらは引き続き第１０期の介護保険事業計画の中の保険料の算定のときも… 私から、１１ページの地域支援事業についてのご説明をします。前年度から減っている理由については今すぐにお答えできる材料がないのですが、ただ、それに伴う各事業は引き続き実施をしています。","id":"exchange-017"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ、本当は取り崩してすごく少なくなる予定が逆に増えてしまっているのが実態なので、この基金はぜひ活用して保険料を引き下げていただきたい。この段階も品川区の場合は１７段階で、この保険料はさらに高額所得者に応能負担をしてもらうという段階にぜひしていただきたい、これは要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"やなぎさわ委員","kind":"質問","question":"低所得者対策についてお伺いしたいのですけれども、この１２件の内訳が、その状況がお分かりになりましたらお伺いしたいです。","respondent":"佐藤高齢者福祉課長","answer":"申し訳ございません。内訳の把握はしておりませんけれども、委員ご指摘のとおり、この間、漸次減少しているという実態です。","id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"質問","question":"１０分の１以下になっていて、平成１３年と現在で、基準が変わったり何か変更があったりしてこれだけ減っているのでしょうか。その辺お伺いしたいと思います。","respondent":"佐藤高齢者福祉課長","answer":"こちらの特例減額は、事業パンフレットも置いておりまして、受け付けているところではありますけれども、減少している理由については、こちらでは把握していない状況です。","id":"exchange-020"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そして、この特例減額についての周知もしっかりしていただきたいと思っているのですが、ちなみにその周知についてはいかがでしょうか。どのような周知をされていらっしゃるのか、お伺いします。","respondent":"佐藤高齢者福祉課長","answer":"周知については、先ほど申し上げましたけれども、制度のパンフレットですとか、そういったところで、なるべく目につくような形で周知はしております。","id":"exchange-021"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"１２件をどれぐらい捕捉できているのか、しっかり中身を分析して、周知に努めてほしいと求めました。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"吉田委員","kind":"提案","question":"そこにしかるべきサポートができると思うのですけれども、支払いが滞るようになったとか、そういうことについての対策は検討されているのでしょうか。そういうような、ここの所管から、そういう課題が起きているということを庁内での課題に取り上げることは無理なのか尋ねました。","respondent":"佐藤高齢者福祉課長","answer":"あるいは区民の方もありますし、あるいは在宅介護支援センターのケアマネジャーが地域に出ておりますので、そういったことは聞くところであります。","id":"exchange-023"},{"speaker":"吉田委員","kind":"意見","question":"いっぱい来ること自体が、もう受け止める側には難しい状況である人たちがこれから増えていくことは認識の上、対策を考えてほしいと求めました。これはもうお願いするしかないので、以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問","question":"介護認定を受けている方が、品川区の場合は要介護３以上ですけれども、認定証が発行されれば障害者控除とか特別障害者控除が受けられるのです。そこを知らない人がすごく多いと思っていまして、その周知をぜひお願いしたいと思うのですが、いかがか尋ねました。","respondent":"佐藤高齢者福祉課長","answer":"障害者控除については、要介護３以上の方について、現在ですけれども、認定証を申請に基づいてお出ししている状況です。先ほどの議論でもありましたけれども、なかなか届きにくいところはありますので、どういうツールがいいか継続的に考えていきたいと思います。","id":"exchange-025"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"分かりました。できればこの中に、件数だけではなくて金額もぜひ次回以降は入れてほしいと求めましたので、要望だけします。","respondent":"菅野福祉部長","answer":"以前、独自の介護保険料の特例減額を実施していた経過がありまして、その制度がずっと残っていたというところです。ただ、ゼロではないと、この制度はまだまだ生きていますので、しっかりと周知はしていきたいとは思っております。","id":"exchange-026"}]},{"id":"topic-03","title":"令和７年度５歳児健康診査事業の検証結果と令和８年度の取組み","agenda":"令和７年度５歳児健康診査事業の検証結果と令和８年度の取組み","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"取り組んでいかなければならないと思うのですが、区としてどう考えられているのか、伺いたいと思います。令和８年度が５２園で１,０００人に拡充してこれからやっていくということで、ぐっと広げられるわけですが、その見通しについても伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"やなぎさわ委員","kind":"確認","question":"先ほどの鈴木委員の質疑と重なる部分で一応確認ですけれども、大体４.５倍ぐらいに増えると思っておりまして、人員確保の問題で改めてお伺いしたい。改めて、ここら辺の課題はきちんと解決できる見込みはあるのか尋ねました。","respondent":"川村品川保健センター所長","answer":"国の調査でも、あるいは都の調査でも、医師の確保が多分一番課題になっているところで、我々としてもその課題に向けてしっかりと取り組んです。しっかりと確保して、健診を実施した後、しっかりと支援につながるように担保していきたいと考えております。","id":"exchange-028"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"全国的に５歳児健診が始まると、難しい部分もたくさんあると思いますけれども、やはり課題として取り組んでほしいと求めました。その分、今日の最初の令和７年度の障害福祉計画の実績等にも絡んできますけれども、発見ベースと同時に受皿の拡充も併せて要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.30ko.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":29,"characters":35698,"voices":102}},{"id":"r08-20260630-8","meetingId":"r08-m0708","date":"2026年6月30日","dateIso":"2026-06-30","committee":"建設委員会","time":"午前１０時００分～午後１時４６分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件整理しています。","topics":[{"id":"topic-01","title":"大崎西口駅前地区（大崎駅西口Ｆ東地区）の再開発事業に係る事業者による近隣説明会の 開催","agenda":"大崎西口駅前地区（大崎駅西口Ｆ東地区）の再開発事業に係る事業者による近隣説明会の 開催","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"３番、都市計画法第１６条・第１７条の説明会、伺いたいと思います。地区内の権利者数等について全体像を伺いたいと思いますけれども、地権者数というのですか、伺いたいと思います。","respondent":"中道都市開発課長","answer":"こういった近隣の説明会をして、そういったことを踏まえて、今後の状況等を見て手続をするというところだと考えています。マンションは、１つのマンションで１名という形で、マンションごとで加入していると報告を受けているところであります。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"何というのですか、まだこれはこの時点で白紙だということを、しっかりと行政も意識してほしいと求めました。今回の近隣説明会の開催を行政が許可して、今回、建設委員会に報告することにしたのかなどを伺いたいと思います。","respondent":"中道都市開発課長","answer":"そうした中で約８割以上の方が、いわゆる近隣説明会を行って、周辺の地域の方々のご意見も聞きたいということを言われている状況です。ですので、今そういった経緯の中で説明会を行うということになりましたので、区といたしましては常任委員会で報告しています。","id":"exchange-002"},{"speaker":"安藤委員","kind":"提案","question":"課長は８割以上という話は聞いていると伺いましたけれども、先ほど紹介した、８割同意ではないという疑義が出されているわけです。近隣説明会の開催について、指針に適合していると考えているのか、伺いたいと思いますとの意見を述べました。","respondent":"中道都市開発課長","answer":"状況等も今現在、８割以上の同意があるので説明会を開催したいという話がありますので、報告を受けたという形になってあります。地域からの８割合意が得られたということは聞いてはいますので、説明会をして、十分に議論が尽くされた中で都市計画に進めていきたいと考えています。","id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"６月２９日付の、私は確認していないのですけれども届いていると思うのですが、「再開発準備組合が出そうとしている企画提案書に関しては。８割が同意したという同意書の中には、そういう数字なのか、伺いたいと思いますとの意見を述べました。","respondent":"中道都市開発課長","answer":"今、安藤委員から、当該地に住むことができないというお話がございましたけれども、決してそのようなことではございません。要するに合計２回、そういった負担を少しでもなくしていきたいと考えているということを、報告を受けているところです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"続けて質問をさせていただきたいと思うのですが、はっきり言って、再開発における権利変換でもないし転出でもないのです。要望書などにも書かれていることなのですけれども、だから住替え・移転する方々を含めての８割同意とは、区の見解を改めて伺いたいと思います。","respondent":"中道都市開発課長","answer":"特に、今お住まいの地区内の権利者の方々に対して、都市計画を進める中で同意をするかしないかを聞かないという判断はないかと考えています。","id":"exchange-005"},{"speaker":"安藤委員","kind":"提案","question":"自らが、そこに住みたいという方々の要望には応えられない計画を進めようとしているわけですから、一層努力をしなくてはいけないのではないかと。改めて、この企画提案書を受ける段階なのかどうかを判断していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"区は、そういった様々な声に対しては、きちっと受け入れる体制はありますので、また何かございましたら、私のところに来ていただければ、そういったお話は聞いていきたいと考えています。","id":"exchange-006"},{"speaker":"安藤委員","kind":"提案","question":"最後に借地権についても伺いたいのですが、区域内の土地の所有権者および借地権者のそれぞれ３分の２以上の同意を得ることを求めています。ですから、１つは、増えたということなのか尋ねました。","respondent":"中道都市開発課長","answer":"今、正確に数字をお答えすることはできないのですけれども、複数名いるということは今確認しているような状況です。借地権者の３分の２以上の同意が必要だというところで、もし仮に１名ならば、区はそのような状況ではないという認識です。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"３分の２ですから、そのうち１名の方が反対しているわけですから、そうすると２分の１にしかならない。行政としてまずいのではないですかということと、あと、見通しが立っていないという意味を教えてもらいたいと思います。","respondent":"中道都市開発課長","answer":"まずは近隣説明会を開催して、十分、行政としては把握していきたいと考えているところです。１人ではなくて複数名いるですけれども、されないのかというのは、きちっと行政としても把握していきたいと考えています。","id":"exchange-008"},{"speaker":"安藤委員","kind":"提案","question":"企画提案書を受け取ったら都市計画手続が始まり、そして先ほどのスケジュール、半年ぐらいで都市計画決定まで行ってしまうわけではないか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"こんの委員","kind":"提案","question":"参考までに伺いたいのですけれども、住民説明会の持ち方といったところです。企画提案書が作られる前に住民説明会をするみたいなことが今まであったのか、住民説明会の持ち方みたいなものは、参考までに伺いたいと思いますとの意見を述べました。","respondent":"中道都市開発課長","answer":"大崎東口第４地区ですと、権利説明会を行いまして、再開発の中でも努力してほしいみたいなお話がありました。１年間ぐらいかかったのですけれども、こういった近隣説明会を行って、理解した上で進めていくというところが非常に重要だと考えています。","id":"exchange-010"},{"speaker":"こんの委員","kind":"提案","question":"そうすると、やはり企画提案書の前に住民説明会を行うというのはありだといったところですか。よくよく、企画提案書が作られる前の住民説明会、進めるに当たってはこうしたことが必要だということは今確認させていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"おぎの委員","kind":"質問・要望","question":"今このエリアに関する区の見解等がありましたら教えていただきたいのと、居住者、該当エリアの方以外も聞きに行くことができるのか。そういった説明会が広く、ほかの方も聞ける状態なのか、もし聞いていたら教えてほしいと求めました。","respondent":"中道都市開発課長","answer":"再開発の説明会の範囲ですけれども、今冒頭で説明した、対象としてはその方々にはなるのかと考えております。その混雑状況を見ながら、説明を聞けるのであれば聞いていただけるよう、準備組合には相談したいと考えています。","id":"exchange-012"},{"speaker":"おぎの委員","kind":"質問・要望","question":"しっかりと近隣の方の意見が聞けるような状況を、区としても適宜アドバイスなどしながら介入してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"資料３ページ目のほうですけれども、特にどのような施策と取組が大切だと考えていらっしゃるのか、伺います。それで意見自体も、説明会をすることで増えると思うのですけれども、こちらも伺いたいと思います。","respondent":"原交通安全担当課長","answer":"続きまして、説明会につきましては、現時点では説明会の実施は考えておりません。実施に当たりましては、要綱上の最長期間である３０日間を設定して、意見を募らせていただく予定です。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"区の基本的な計画のパブリックコメント時には説明会を位置づけるよう求めたのですけれども、それに対して当時の区長室長が、「説明会等も含めて。こういった、説明会も併せて行うということを当たり前にしてほしいと求めましたので、これは要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"こんの委員","kind":"確認","question":"この計画の中から確認というか、「総合的な対策を」と目的の中にもありましたので伺っていきたいのですが、もう一つが道路標識の設置といった角度。この２点をお伺いします。","respondent":"森道路課長","answer":"あるいは設置できる・できないの区別なく、安全にするために必要な設備というものはしっかりとつけていきたいとは思っております。標識というよりは、そういったものと組み合わせながら、逆走の防止などといったところは進めていきたいと思っています。","id":"exchange-016"},{"speaker":"こんの委員","kind":"質問・要望","question":"私道ですから、住民の方の要望でもあるのですが、生活に必要な車というのは入ってくる。今後こうした課題について研究しながら、警察と協議していってほしいと求めましたが、いかがか尋ねました。","respondent":"原交通安全担当課長","answer":"こちらはまだ素案ですので、今後、そういった部分の記載についても考えさせていただきたいと思います。実際に実施の要領といたしましては、総合的に検討させていただきまして、そういった対策を続けていきたいと考えています。","id":"exchange-017"},{"speaker":"こんの委員","kind":"質問","question":"もう一つ、道路交通環境の整備という角度で１つお伺いしたいのですけれども、これは、お宅の建て替えをしたときに、電柱がそばにある。なぜ残ってしまうという課題が生じてしまうのか、その課題についても伺いたいと思います。","respondent":"森建築課長","answer":"電柱が近づいてくることによって、建物によじ登って入ってくるかもしれない懸念があるというのは聞いたことがあります。建築課の職員からも、何度も建て主に対して説明して、ご理解いただけるように努めているところです。","id":"exchange-018"},{"speaker":"こんの委員","kind":"質問","question":"そうしたことで、なかなかそのことをご理解いただけないというのが１つあるというのは、実際にそういうご相談を受けたことがあります。ご理解いただけるようなやりようがないのかというところを伺いたいと思います。","respondent":"森建築課長","answer":"１つの事業者からは、どうしても難しい。ただ、粘り強く、電柱の事業者に対して、区からの支払いでいいのではないかということは、引き続いて交渉を続けてまいりたいと考えています。","id":"exchange-019"},{"speaker":"こんの委員","kind":"意見","question":"このことが１つクリアになると、ぜひ引き続き、その点の交渉をお願いしたいと思います。それが促進につながると、 こうした電柱が残るということの課題も解消につながるのかと思いますので、どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"計画概要の中で、特に６番の「特定小型原動機付自転車を始めとする小型モビリティの安全対策の推進」は本当に強化していただきたいと考えています。品川区としても問題だと思うので、今後これをどういうふうに推進・強化していくというのを、今現在のことをお知らせしてほしいと求めました。","respondent":"原交通安全担当課長","answer":"都内全体で２８０件、前の年からプラス３６件といった形で、やはり特定小型原動機付自転車も広く普及し続けているといった現状で認識しております。引き続き、警察と連携して、各種活動、指導・啓発を行っていきたいと考えているところです。","id":"exchange-021"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そういった中で、２点だけ質問をします。これは本当に私の要望としてなのですけれども、そのことについて２点、何かあればお話しほしいと求めました。","respondent":"原交通安全担当課長","answer":"子どもや高齢者に対する対策につきましては、それぞれ、高齢者につきましてはシルバー人材センターに対する安全教室・安全教育等を実施しております。","id":"exchange-022"},{"speaker":"おぎの委員","kind":"質問・要望","question":"大分、聞きたいことが、全く同じものが出ておりましたので、最後に要望だけお願いしたいと思います。以上要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"えのした副委員長","kind":"質問・要望","question":"区内２,０００本ということで、やはり日々の一本一本の安全確認が、この場をお借りして感謝を申し上げます。まだ４月からですから、数が分かれば教えていただきたいのですが、いかがか尋ねました。","respondent":"原交通安全担当課長","answer":"今ご質問いただきました、今年の４月から青切符制度が導入されたことによる情勢の変化についてご説明いたします。４月・５月の２か月に限ってみますと、マイナス約２０件といった形で、こういった４月以降の状況となっております。","id":"exchange-024"},{"speaker":"えのした副委員長","kind":"質問・要望","question":"事故が増えた理由が様々ある中で３点、６５歳以上の割合が高い、作成してほしいと求めました。こちらは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"こんの委員","kind":"質問","question":"副委員長からの質問に少し関連するのですが、違法駐輪対策を考えていくのか、現時点でのお考えをお聞きしたいと思います。","respondent":"原交通安全担当課長","answer":"緊急車両の通行を妨げたり、車椅子やベビーカーなど、様々な人が通行できる環境を阻害するものと考えております。これまでも進めております駐輪場の整備と、あとは放置禁止区域を適宜設定して、そういった違法駐輪の車両の除去に努めていきたいと考えております。","id":"exchange-026"},{"speaker":"こんの委員","kind":"質問","question":"いわゆる撤去作業を軽減できるような対策はないのかなどというのを、今後研究されていくのはどうなのか。こうしたところの観点というのは、どんなふうに今お考えをお持ちなのか、お聞きしたいと思います。","respondent":"原交通安全担当課長","answer":"そういったところが常態化しているような地域等を把握しましたら、その付近に対して警告を行うといったことも検討していきたいと思います。２３区、ほかの区の取組なども共有しながら、引き続き違法駐輪対策をしていきたいと考えています。","id":"exchange-027"},{"speaker":"こんの委員","kind":"質問","question":"そうしたところから、私もまだまだ研究段階ですけれども、そうした施策を考えていらっしゃる企業なども出てきております。どうしたら、予算を使わなくても済むようなところという観点も、これから併せて研究も調査もしながら進めてみてはいかがか尋ねました。","respondent":"原交通安全担当課長","answer":"区といたしましては、今、委員のお話がありましたとおり、現状の事業は継続しつつ、民間企業など、 そういった研究が行われていることについても注視しながら、今後の業務に反映できるように考えてまいりたいと思います。","id":"exchange-028"}]},{"id":"topic-02","title":"電線共同溝等工事（特別区道Ⅰ－２４１号）の委託","agenda":"電線共同溝等工事（特別区道Ⅰ－２４１号）の委託","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"品川区の職員ということでいいのか確認したいのと、伺いたいと思いますし、どちらなのでしょうか。伺いたいと思います。","respondent":"森道路課長","answer":"そういった部分を柔軟に工程管理ができるようになるということで、ほかの区でも今回の方式でやられているので、それを進めていきたいと考えています。コスト面については、全体的なスケジュールが短縮されたり、それぞれの事務費が減少するということはあるかと考えています。","id":"exchange-029"},{"speaker":"こんの委員","kind":"質問","question":"いわゆる電柱が建っている道路の占用料といったところを伺いたいと思うのですけれども、地中化になった場合の占用料はどうなるのでしょうか。参考までに伺いたいと思います。","respondent":"川崎土木管理課長","answer":"占用料につきまして、今、区道上に建っている占用に関しては徴収はしておりますけれども、地中化になることで減免ということにはなっております。","id":"exchange-030"},{"speaker":"こんの委員","kind":"質問","question":"どれぐらいの減免になるのかというのを参考までに伺いたいのと、電柱が外に出ている場合、割とばらつきがあるみたいなお話も聞いたことがあります。そうしたときに、品川区の占用料というのは他区と比べてどれぐらいなのかというのが今お分かりになれば、その辺も参考までに伺いたいと思います。","respondent":"川崎土木管理課長","answer":"今、減免の料金につきましては、また後ほど、回答します。通常よりも、安いという言い方はできませんけれども、全体で捉えますと平均の単価を採用しながら徴収しているという形になっております。","id":"exchange-031"},{"speaker":"こんの委員","kind":"確認","question":"この占用料が、ひいては電気料金にも関わってくるといったところのお話を伺ったことがあったので、この機会なのでお聞きさせていただきました。先ほど確認させていただいた占用料にも関わってくるとなると、こうした観点からも地中化は必要なのだということを確認させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"えのした副委員長","kind":"質問","question":"民間の専門的技術・民間活力の導入による、他の区でも採用されている方法、包括して委託するためというような理由からなのでしょうか。そちらを説明するよう求めました。","respondent":"森道路課長","answer":"それを移動させていくということになりますと、実質的に東京電力のグループとＮＴＴのグループしか作業できないということになってまいります。ですので、今回は東京電力に随意契約という形でやらせていただいているところです。","id":"exchange-033"},{"speaker":"えのした副委員長","kind":"質問","question":"理解いたしました。今、ほかに光ファイバーやケーブルテレビのケーブルなども一緒に進めているという話なのですが、今回はどのような形で進められるのか尋ねました。","respondent":"森道路課長","answer":"有線やケーブルテレビも同じように管を設けて、その中に線を入れていくことになりますので、基本的には全ての電線が地下に入るということになります。","id":"exchange-034"}]},{"id":"topic-03","title":"（仮称）勝島人道橋上部工の架設","agenda":"（仮称）勝島人道橋上部工の架設","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"今回、深夜にやっていたというのは、水位を使ってということで深夜にやっていたということでしょうか。今後の工事はまた昼間の工事に戻るのか、その辺をお願いいたします。","respondent":"森道路課長","answer":"夜に進めたですけれども、潮がだんだん下がってくるというものを利用して、それで下ろしてくるという工法を採用しております。ですので今回は、大潮ですけれども真夜中の設置になったです。","id":"exchange-035"},{"speaker":"おぎの委員","kind":"意見","question":"こちらができて、また人の流れや、ウオーキングの方たちの回遊性などもできたりするのかなと考えています。課が違うかもしれませんが、ぜひ開通の際には、両方の町会の方なども呼んでいただいて、皆さんでこちらの開幕式をやっていただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"}]},{"id":"topic-04","title":"子どもの森公園改修工事","agenda":"子どもの森公園改修工事","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"以前にも伺ったのですが、引き続き使用していただきたいのですけれども、いかがか尋ねました。","respondent":"大友公園課長","answer":"状態のよいもの３体を残し、合計１０体の恐竜を整備するという形で以前ご説明させていただきまして、その中に。現在ある１０体の恐竜のうち４体が補修で、７体を新設し、計１１体の恐竜を設置するという予定です。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"もう一度だけ伺いたいのですけれども、ある程度お金をかければ再利用できるのではないかと思うのですけれども、その辺はいかがですか。現在の予定では、今残っている黄色い肉食恐竜が撤去されるのは、いつぐらいの工事予定になるのかというのも伺いたいと思います。","respondent":"大友公園課長","answer":"１体が、ポスターなどにも使われている恐竜というところについては、難しいという判断がされているところです。代わりに、人を呼べるようなモニュメントというところでのテーマの恐竜も設置されますので、新たな魅力を発信していきたいと考えているところです。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"とても残念だというか、何とか最後の最後まで、手はないかということを考えていただければということで、これは要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"こんの委員","kind":"質問","question":"１点お聞きしたいのですが、水浴びができるような場所があったかと思うのですけれども、そこは残るのでしたでしょうか。その辺を伺いたいと思います。","respondent":"大友公園課長","answer":"水を一定、感じることができて、そこで遊べるようなポールというのが新たに新設はされます。その場所についてなのですけれども、少し説明しにくいのですけれども、公園中央部ぐらいになる見込みです。","id":"exchange-040"},{"speaker":"こんの委員","kind":"確認","question":"場所は変わっても残されるということを確認できましたので、引き続き、改修をよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]},{"id":"topic-05","title":"を続けます。 次に、⑹東大井公園改修工事","agenda":"を続けます。 次に、⑹東大井公園改修工事","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"その結果、反映された部分というのはどこなのかなども伺いたいと思います。環境に優しいタイプの人工芝にして、環境や利用者に配慮していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"大友公園課長","answer":"この特別支援学校のヒアリングを実施した結果というところ、インクルーシブな遊び場としての公園整備を決定しています。有効な手段といたしまして、排水工にフィルターを設置するということで、マイクロプラスチックの流出を防ぐ対策を実施して工事を行ってまいります。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後まで工夫して、なるべく環境に負荷がないようなものにしていただきたいと思うのですけれども、再度お伺いします。","respondent":"大友公園課長","answer":"ほかの人工芝に比べて、そのような流出が少ないというところで、環境に配慮した人工芝を採用しています。","id":"exchange-043"},{"speaker":"こんの委員","kind":"確認","question":"工事直接のことではないのですけれども、工事に関連して１点確認させてください。改修に当たっては、その格納庫はどのようになるのか、ご存じでしたら説明を求めました。","respondent":"大友公園課長","answer":"格納庫については、既存の倉庫を移設する形で考えてあります。出入口付近の利便性の高いところに既存の倉庫を移設してまいりますので、そのまま活用いただく形で考えております。","id":"exchange-044"},{"speaker":"こんの委員","kind":"質問・要望","question":"あまり消防団のことばかり要望というわけにはいかないのですが、できれば今まであった西側の方面のどこかに移設というふうに考えられるのですが、具体的な場所がもし今分かっているようでしたら説明を求めました。","respondent":"大友公園課長","answer":"西側の道路に接した形の場所になりまして、公園の位置でいきますと、北西の位置に移設してまいります。","id":"exchange-045"}]},{"id":"topic-06","title":"西大井広場公園（北側）改修等工事","agenda":"西大井広場公園（北側）改修等工事","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"こちらは整備台数の考え方というのはどういう考え方なのかというのをお伺いしたいのと、これは何を指しているのかを教えてください。どういう形でどういうところから意見を募ったのか、意見を募った上で反映された部分というのはどこになるのか、伺いたいと思います。","respondent":"大友公園課長","answer":"まず公園に、駐輪場の整備に至ったというところの経緯からご説明させていただきたいのですけれども、また区民まつりおよび防災イベントの実施など。４３０戸にアンケート調査を実施しているほか、近隣３か所の保育園などにヒアリングを実施して、改修計画をつくっているです。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"ここの駐輪場はそのようになるのか、それとも料金を徴収するというところになるのか、伺いたいと思います。区内の駐輪場などでは初めてのことなのか、これからこういったところは広げていく考えなのか、伺いたいと思います。","respondent":"原交通安全担当課長","answer":"なお、またこちらの設置につきましては、西大井駅の建屋の駐輪場がございまして、こちらの改修と併せて行っていく予定です。普通自転車用のところはラックの使用を予定しておりまして、大型自転車用のスペースにとめていただくという形で利用していただいているところです。","id":"exchange-047"},{"speaker":"安藤委員","kind":"確認","question":"建屋のほうは、建屋のほうは当日利用を減らして定期利用を増やすということなのか、確認させてください。最初の２時間は無料だということで、公園の利用者の皆さんに、そちらも併せて最後にお伺いします。","respondent":"大友公園課長、原交通安全担当課長","answer":"改修を行いませんけれども、利用できる駐輪場ができるというところの案内を、積極的にしてまいりたいと考えているところです。 定期利用が２７４台、当日利用が約１６０台で運用していますが、建屋のほうは全て定期利用で約４００台がとめられる状態にする予定です。その分、建屋の当日利用を、公園のほうの駐輪場を利用していただくということを考えております。","id":"exchange-048"},{"speaker":"こんの委員","kind":"確認","question":"そういうものをイメージしているのかの確認が１点。工事の１日にできる時間帯などがあると思うのですけれども、ここは少し、工事はどういうふうに行われるのか尋ねました。","respondent":"大友公園課長","answer":"大型の駐輪についてなのですけれども、大型はいろいろ三輪のタイプなど、様々な形があると思いますので、平置きを基本としているという考えです。","id":"exchange-049"},{"speaker":"こんの委員","kind":"質問・要望","question":"それから工事の時間帯、多分、保育園からは何も声が上がっていないのかもしれないですが、できれば配慮していただけると助かります。無事故で安全に工事を行ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]},{"id":"topic-07","title":"公園における花火の使用","agenda":"公園における花火の使用","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"来年度に向けて反映していきたい、昨年実施してみて、どんな声がどのぐらい寄せられたのかというのを伺いたいと思います。昨年の試験的な取組では、どのような試行結果といいますか、それが得られたと考えていらっしゃるのか伺いたいと思います。","respondent":"大友公園課長","answer":"このような使用状況・利用状況を踏まえまして、公園の管理者がいる公園で実施を継続するというところが必要であると考えたところです。公園の拡大をすると、公園管理者がいないというところで、そのような対応ができなくなるというところで、今回も５公園という形で実施していく。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問","question":"やはり、親子で花火ができるという環境というのは、都心ですけれども、都心だからこそ確保したいという思いはあります。その問題はクリアできたのでしょうかというのをお伺いしたいと思いますし、しながわ区民公園だけ時間が短い理由は何なのかも説明を求めました。","respondent":"大友公園課長","answer":"そういうところにつきましては、公園管理者がいる公園での実施というところで、 巡回するという対応で課題をクリアできると考えているところです。閉鎖型公園であるというところで、一定時間には出ていただかなくてはならないというところで、時間を前倒ししているところです。","id":"exchange-052"},{"speaker":"安藤委員","kind":"意見","question":"分かりました。ぜひ今年もやって、様々なご意見も頂きながら、来年も継続できるように実施していってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"}]},{"id":"topic-08","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"６月２６日のこしば議員の地域公共交通についての質問で、改めて今後の区全体の公共交通をどうしていく考えなのか伺うと同時に、現時点での区の考え方を伺いたいと思います。","respondent":"あくつ委員長、櫻木地域交通政策課長","answer":"その前提の中で、アンケー トの部分、お答えいただける部分でご答弁いただければと思います。ご答弁をお願いいたします。現在、区全体の公共交通ネットワークを整理する中で実施が想定されるアンケートにつきましては、現時点では概要や時期等は未定です。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"何のためにアンケートをやるのですかというところ。今後、コミュニティバスを増やすという考えがあるのか、バス事業者に対して支援などといったものを行う考えがあるのか、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"概要や時期というよりも、何のために取るのかという目的について質問をしているのですが、少しはっきりしない答弁なので、もう一度だけお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"}]},{"id":"topic-09","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"出席希望ではないです。私たち共産党としては、道路大会というのは趣旨に反対なものですから、参加しないということの意思表示をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.30ke.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":41,"characters":51286,"voices":177}},{"id":"r08-20260630-9","meetingId":"r08-m0708","date":"2026年6月30日","dateIso":"2026-06-30","committee":"文教委員会","time":"午前10時00分～午後１時38分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件整理しています。","topics":[{"id":"topic-01","title":"学校改築の進捗","agenda":"学校改築の進捗","exchanges":[{"speaker":"西本委員","kind":"確認","question":"それについての説明を近隣住民たちにきちんとしていますかということを確認したいと思います。この２つお願いします。","respondent":"荒木学校施設担当課長","answer":"こちらは教育委員会といたしましては、あとは工事を着工する前に工事説明会というものをそれぞれ開きまして、近隣の方々へご説明をしております。は風向きといったところも丁寧に説明いたしまして、防音設備を設置したり、そういったような配慮に努めているところです。","id":"exchange-001"},{"speaker":"西本委員","kind":"確認","question":"校庭が潰されるという感覚になるので、校庭等での授業についての確保というものは、それぞれできているのですよねということを確認させてください。お願いいたします。","respondent":"荒木学校施設担当課長","answer":"１点目の工期の工程に関しましては、近隣住民への影響を可能な限り避けることを目標として、今後も進めてまいりたいと考えております。は老朽度、それから地域バランスなどを総合的に勘案した上で、柔軟に改築計画を進めてまいりたいと考えています。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"ですから、これから１８校やるにしても、改築できない状況になるのではないかなと私は思うのです。１０年、２０年使えるようにしていくのかという、教育に使う予算の考え方を最後に説明を求めました。","respondent":"荒木学校施設担当課長","answer":"現在は建て替えをメインで進めてきたわけなのですけれども、新しい手法も何かないかというところも含めて、検討はしていきたいと考えています。","id":"exchange-003"},{"speaker":"ゆきた委員","kind":"質問","question":"その点について、東海中学校においても同様の考え方で整備を予定しているのかということを改めてお聞きしたいと思います。ここが冷暖房設備を備えた採暖室も含まれているというように理解してよろしいのかお聞きしたいと思います。","respondent":"荒木学校施設担当課長","answer":"１点目の、この資料でいうところの右上の５階平面図、水面の上部のほうには日よけシェードなどで覆うという計画を検討しています。２点目の、北側の諸室の一部をそういったような採暖室、空調の効いた部屋に充てようと考えています。","id":"exchange-004"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"２つとも確認できました。こちらは要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"澤田委員","kind":"質問","question":"私からは特別支援学級のことをお伺いしたいのですけれども、浅間台小学校に特別支援学級もありますし、大変うれしく思っています。区としての考えをお聞かせいただけますか。","respondent":"荒木学校施設担当課長","answer":"今後詳細なしつらえにつきましては、現在進めている実施設計で検討してまいりたいと思います。今後も教育委員会の中で連携しながら、必要なスペース確保に努めてまいりたいと考えています。","id":"exchange-006"},{"speaker":"澤田委員","kind":"意見","question":"広さをしっかり確保していただけるように進めてくださっているということで、安心しました。これからもぜひ、カーミングルームというか、落ち着けるスペースなど、いろいろ配備を進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"確認","question":"そうすると三木小学校と大崎中学校をやるまでが、しばらく間が空くのかなということがあるのですが、そこの確認です。これ固定級を５つにするということですから、そのような傾向を今、 先読みしているのかなというところがあるので、そこです。","respondent":"荒木学校施設担当課長、新井特別支援教育担当課長","answer":"もう１点、ストレッチャー対応のエレベーターですが、ストレッチャー対応のエレベーターとして整備をしています。公共施設の各所管と可能な限り調整は進めて、工事中の学校運営が可能な限り円滑に進むように… ２点目の東海中学校の特別支援学級の種類についてなのですが、まだ知的障害にするのか、自閉症・情緒障害とするのかについては検討中です。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"運動スペースというのですか、そのような方も、理解していただけると思うのです。でも、本当に何か月に１回でもいいから広いところで運動できるような手だてをぜひ、これは要望でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-02","title":"令和９年度新入学者の受入枠","agenda":"令和９年度新入学者の受入枠","exchanges":[{"speaker":"西本委員","kind":"質問","question":"ですから、上神明小学校、清水台小学校、小山台小学校は３０人程度なので、そこも２クラスぐらいになるといいのかなと思っているのですが。その現状はどうか尋ねました。","respondent":"石井学務課長、新井特別支援教育担当課長","answer":"ただし、住民基本台帳上は、当然特別支援学級の対象の方も含まれておりますので、 そういった中での調整になってくると考えています。は全体的な傾向としては増えてきているというような認識です。新１年生の特別支援学級のお子さんの数としては８人ということで、特別支援学級を設置されているほかの学校との割合で見ても。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、特化してしまうという、そのようなことをやってしまってもいいのかなと思っているのです。それとはまた別に、何でしょうか、いいことはいいことなのです。","respondent":"石井学務課長、新井特別支援教育担当課長","answer":"昨日ご説明いたしました、増要因と減要因にそれぞれ転入、転出というような数字があります。単年度比較なので、これがどんどん、一定程度学区によってもばらつきがあるのではないかなというように想像しております。例えばこの４月から自閉症・情緒障害の特別支援学級を開設したといったところの、保育園、自閉症・情緒の学級を小学校に設置している自治体が。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"インクルーシブなどいろいろありますけれども、要は生徒・児童の育ちの環境として、いろいろなケースが必要になってくると思うのです。今後、本当に一人ひとりに目の行く教育というものをぜひ目指していただきたいなというように要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"ゆきた委員","kind":"質問","question":"地域の保護者の方々から、例年以上に希望校へ進学しにくかった、待機となって最後まで空きが出なかったという声も伺っております。そこで、３５人学級の導入が学校選択にどのような影響を与えたということで認識しているのかお聞きしたいと思います。","respondent":"石井学務課長","answer":"昨日も受入れ、入学率のことについて、実は説明いたしました。そこに３５人学級の影響も相まったことが、この学校選択制における入学率の低さにつながっているのではないかなというように見ているところです。","id":"exchange-013"},{"speaker":"ゆきた委員","kind":"質問","question":"保護者が見通しを持って判断できるように、もう理解できるように、これまで以上に分かりやすい情報提供が重要であると考えています。学校案内や、こうした点についてより丁寧な情報提供をさらに進めていってほしいと求めましたが、この点についてお聞きしたいと思います。","respondent":"石井学務課長","answer":"やはりこの３５人学級の影響というもので、案内については、さらにそこについては強調していきたいと考えています。で、まだ選択肢は残っているというような段階で１つ有意義なものだと考えていますので、きちんと説明も行ってまいりたいと考えております。","id":"exchange-014"}]},{"id":"topic-03","title":"「品川区附属機関の構成員の報酬および費用弁償に関する条例の一部を改正する条例」の概 要","agenda":"「品川区附属機関の構成員の報酬および費用弁償に関する条例の一部を改正する条例」の概 要","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"今回の改正の理由が人材確保と今おっしゃっていたと思うのですけれども、需要が増えているのは分かりますが、実際どのような状況なのでしょうか。やはりきちんと仕事をしてほしいと求めましたし、だけれども、その現状を教えていただけますか。","respondent":"保土澤教育総合支援センター長","answer":"今、まさにご指摘のとおり、しっかり専門職である人材を確保して、この委員会を適切に運営していくための改正というところは、まずお伝えします。児童精神科医など、各ご専門の先生方に委員をお願いして、いじめ対策委員会を進めているところです。","id":"exchange-015"},{"speaker":"西本委員","kind":"確認","question":"下手すると３万５,０００円や５万円などにしないと人材確保できないという、そのようなレベルなのでしょうか。これで大丈夫ですかということを確認したいと求めました。","respondent":"保土澤教育総合支援センター長","answer":"さらにほかの自治体の現状を調査し、ほかの自治体よりは高い金額で設定して、しっかりと人材を確保していくという金額になってあります。ちなみに他自治体の１事例をお伝えしますと、必ずしも委員会の迅速な審議に結びつかない課題があるというような自治体もあると伺っています。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"１万９,０００円や３万円ですから。このいじめ対策というものは、非常に大切なことですから。","respondent":"保土澤教育総合支援センター長","answer":"今ご指摘いただいたとおり、我々もこの委員会を非常に重要な機関だというように認識しております。必要な金額、そして可能な金額で、人材をしっかり確保して進めてまいりたいと思っています。","id":"exchange-017"},{"speaker":"ゆきた委員","kind":"質問","question":"１件当たりおおむね何日程度活動することを想定しているのか、どの程度の日数が必要となってくることを想定しているかをお聞きしたいと思います。今回の報酬額は、先ほど他自治体から比べると高い報酬額になっているとお聞きしましたけれども、お聞きしたいと思います。","respondent":"保土澤教育総合支援センター長","answer":"いじめ対策委員会実施の際の人数ですけれども、委員長を含め、現在８名体制で行っております。大体１回当たり２時間から３時間で実施をしておりますので、そのときにお支払いをする金額というようになっております。","id":"exchange-018"},{"speaker":"ゆきた委員","kind":"質問","question":"そうすると、その委員会に出席した時間ということなので、それ以外の、先ほど申し上げました学校への聞き取りや資料作成、報告書作成など、そういった時間は日額のところに入っていないということとなるという認識でよろしいか尋ねました。","respondent":"保土澤教育総合支援センター長","answer":"学校への聞き取りをしていただく、児童や教職員への聞き取りをしていただくときに、この二、三時間、やはり時間を要するケースにつきましては、この日額をお支払いして、聞き取りという内容で対策委員会を実施したという形で回数としてカウントをしております。","id":"exchange-019"},{"speaker":"ゆきた委員","kind":"意見","question":"理解できました。先ほどあった弁護士や医師など、そういった体制の維持に努めてほしいと求めましたので、お願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"}]},{"id":"topic-04","title":"区立学校におけるいじめの重大事態の発生状況","agenda":"区立学校におけるいじめの重大事態の発生状況","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"これどのような経緯で発覚したのかということを教えていただけますでしょうか。親からの報告なのかとか、ご相談なのかとか、それを教えてほしいと求めました。","respondent":"保土澤教育総合支援センター長","answer":"それまでの経緯を確認し、いじめ等の関連があるというところで、いじめ重大事態という認定をしたところです。いじめＤアンケートなど、そういったところが見られてというようなことではございません。","id":"exchange-021"},{"speaker":"澤田委員","kind":"質問","question":"その児童と保護者の方がどうされているのか心配でありますし、今どうしていったらいいのかというものを持ち合わせていなくて申し訳ないのですけれども、いかがか尋ねました。","respondent":"保土澤教育総合支援センター長","answer":"子どもたちがいろいろなメッセージを出しやすくしていくということは、本当にこのいじめの対応について重要なところだと思っています。どうしたらいいのだというようなメッセージを早期にキャッチして、学校で早期に対応していけるように、学校に指導助言していきたいと思います。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"重大事態ということで認定して、継続中のものが何件あって、解決したものが何件と、実績を教えてほしいのですけれども。説明を求めました。","respondent":"保土澤教育総合支援センター長","answer":"令和４年度から令和７年度までの実績になりますけれども、こちらは全部で３５件対応をしております。１２件はまだ調査中です。","id":"exchange-023"},{"speaker":"西本委員","kind":"確認","question":"１つは、解決した後どのような状況になっているのでしょうか。成果が上がっているのでしょうかというところを説明するよう求めました。","respondent":"保土澤教育総合支援センター長","answer":"ただ、加害と被害の立場にそれぞれ必要な配慮を行いながら、学校生活を続けているというところが実情です。そして周りで見ていても、その後３か月間、同じようないじめ行為がないという状態を学校としてはしっかり確認をして解消という形にしております。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"もっと危機感というか、気持ちというか、をしっかりフォローする体制というものは必要なのではないですか。３か月間ないからいいというわけではないと思いますけれども、いかがか尋ねました。","respondent":"保土澤教育総合支援センター長","answer":"これが３か月程度という認識ですので、やはり目安として３か月程度は必要だという認識の下、やっているところです。個別の指導と全体の指導、これは両方必要なことですので、そこを学校のいじめ対策委員会でしっかり協議しながら進めております。","id":"exchange-025"},{"speaker":"西本委員","kind":"意見","question":"ただ、保護者はどうなのだろうなと。両側のフォローというものをしっかりやっていかないと、結局子どもにつながってきますので、その辺はどうされていますかとの意見を述べました。","respondent":"保土澤教育総合支援センター長","answer":"学校ごとに学校いじめ対策基本方針を示して、いじめがあったときには学校はこのように手続を踏んで対応するというところを明らかにしています。それからサポートをしながら対応していくことが必要ですので、被害のお子さんのケア、そういった指導を続けているところです。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、保護者の方々に隠さない、当事者だけでは済まず、皆分かっているはずなので。もう一つ言いたかったのですけれども、時間があれなので次回の機会にしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"ゆきた委員","kind":"確認","question":"令和７年度は１３件の重大事態が認定されて、多くの案件は現在も調査中ということで、私も区のホームページで確認しました。改めて確認ですけれども、通常委員の５人以内で全案件を調査しているのか、お聞きしたいと思います。","respondent":"保土澤教育総合支援センター長","answer":"現在、私今年度からになりますけれども、今年度委員会に出席している中では、委員長１名、それから委員４名の体制で今までやっております。ちょっとご都合が悪いというときに臨時委員の方にご出席いただいて、必要な人数を確保していじめ対策委員会を進めております。","id":"exchange-028"},{"speaker":"ゆきた委員","kind":"質問","question":"通常の委員の方４人と、委員長が１名いるということで、そして臨時委員が追加でということですね。これについてお考えをお聞きしたいと思います。","respondent":"保土澤教育総合支援センター長","answer":"ご指摘のとおりかなと思います。人数が一定程度必要になる場面というものは当然出てまいりますので、いじめ重大事態の解消に向かっていじめ対策委員会を進めてまいりたいと思います。","id":"exchange-029"},{"speaker":"ゆきた委員","kind":"質問","question":"先ほど報告事項の中でもありましたけれども、委員の人材の確保というものはさらに重要性が増してくると思います。この臨時委員の活用についても、今後の考え方は検討していかなければいけないなと感じていますけれども、その辺についてお聞きしたいと思います。","respondent":"保土澤教育総合支援センター長","answer":"これが今後増えていったときの体制についてのご指摘だと思います。いじめの重大事態を生まない学校のいじめ対応というところを同時に、むしろこちらが本丸かなと考えていますので、先ほどの金額と同じで。","id":"exchange-030"}]},{"id":"topic-05","title":"「品川区特別支援教育推進計画」の策定","agenda":"「品川区特別支援教育推進計画」の策定","exchanges":[{"speaker":"澤田委員","kind":"質問・要望","question":"まず質問をさせていただきたいのですけれども、第１回会議が７月に控えていることを考えると、お聞かせほしいと求めました。","respondent":"新井特別支援教育担当課長","answer":"特別支援教育に関する分野の研究をされている方を委員として選んですし、あとは、そういった方々に今内諾をいただいているような形になります。改めて、第１回の開催を経まして、委員の構成等についてきちんと報告をしてまいりたいと考えております。","id":"exchange-031"},{"speaker":"澤田委員","kind":"質問・要望","question":"ぜひしっかりと話し合っていただけるような方を、知識の広い方、思いのある方を選んでいただければなと考えています。１２月に実施されますが、対象者を教えていただきたいということと、その辺についてお聞かせほしいと求めました。","respondent":"新井特別支援教育担当課長","answer":"委員がおっしゃられたとおり、やはり実際に、非常に大事な視点の１つかなと考えています。そしてパブリックコメントを実施することが伝わるようにしていきたいと考えておりますし、そういった特別支援に関わっているお子さんだけでなくて。","id":"exchange-032"},{"speaker":"ゆきた委員","kind":"質問","question":"今澤田委員からありました委員の構成のところですけれども、委員の構成は何か条例や規約に基づいて、構成員は１４人以内ということに決められているのか、そこをお聞きします。","respondent":"新井特別支援教育担当課長","answer":"私どものほうで、今回この検討委員会の設置要綱を策定いたしまして、その中で教育長が委嘱する委員１４人以内をもって組織するという形で、根拠にやらせていただいております。","id":"exchange-033"},{"speaker":"ゆきた委員","kind":"質問","question":"ここについてお聞きしたいということと、本当に支援の必要な人のお声とは、保護者の声が必要だと思います。どうアプローチしていくのかということを、改めてですけれども、もう一度お聞きしたいと思います。","respondent":"新井特別支援教育担当課長","answer":"は区、まずは広く全区民の方に対してパブリックコメントを実施するということを、きちんとアナウンスしていきたいと考えています。周知や、今後どういったツールを使うかというところは今検討中であるのですが、しっかり届くように周知を図ってまいりたいと考えております。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"町会長だったら町会の意見を総じて言っていただきたいわけではないですか。そのようなことについてはどうお考えになりますか尋ねました。","respondent":"新井特別支援教育担当課長","answer":"これは検討委員会の中で決めていくといったところもあるのですけれども、特別支援学級に通っているお子さん、そういった視点も。福祉の課長も委員として委嘱する予定ですので、あとは保育部門の課長にも委員として委嘱をする予定ですので、そういったところについては。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問・要望","question":"その子の状況に合わせた教育は何でしょうかといったときに、その子特有の、その状況に合わせた教育というものをするべきだと思うのです。ですから、特別支援が必要ではない子たちについては当たり前かもしれないのですけれども、でもやはり社会全体で見守っていくという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問","question":"学校教育法上の学校ではあるのですけれども、世田谷区は明確に含んでいて、品川区の場合は同様にしていくのでしょうか。どのように扱っていくかというところをお尋ねします。","respondent":"新井特別支援教育担当課長","answer":"ただ、重要なところと考えておりまして、検討委員会の委員としても保健センター所長や保育部門の所管課長にお願いしているところであります。","id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"質問","question":"お尋ねしようと思ったのですけれども、先ほどの５歳児健診も近々ですけれども、すごく今までの実績を踏まえて計画を立てられると思うのです。ですから、今、課長がそのようなものを含めて計画していくということですので、大変期待しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"山本副委員長","kind":"提案","question":"これはぜひそういったことを進めて、委員の皆さんにご提案していただいて、そのような機会をつくっていただきたいということがあります。ご意見をほしいと求めました。","respondent":"新井特別支援教育担当課長","answer":"まず１点目の、実施方法をアンケートとするのかといったところについては、検討委員会の委員とも相談をしながら進めてまいりたいと考えております。","id":"exchange-039"}]},{"id":"topic-06","title":"「（仮称）品川区こどもの権利条例」の制定","agenda":"「（仮称）品川区こどもの権利条例」の制定","exchanges":[{"speaker":"西本委員","kind":"確認","question":"これから検討していくので、これから中身を議論していければと思いますけれども、少し確認だけしたいです。そして、１番の背景および目的というところで、これはどのようなものだったのか尋ねました。","respondent":"柴田子ども施策連携担当課長","answer":"こども会議での意見、令和７年度から計画実施しておりますこども計画の策定に当たってアンケートを取った際に、半分にも満たないような状況であった。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"ですから、これから定めていくわけですけれども、それに相反することになっていく可能性もあるわけです。令和１０年度に条例制定となるのですけれども、もう少し早くしてほしいなという気持ちがあるのです。","respondent":"柴田子ども施策連携担当課長","answer":"先ほど委員もおっしゃったように、聞くことは難しいのですけれども、何とか引き出したいと思っています。まだ着手したタイミングですので、策定する段階から、そういった点も意識しながら取り組んでまいりたいと考えています。","id":"exchange-041"},{"speaker":"西本委員","kind":"提案","question":"１つの提案なのですけれども、自ら話をすることは難しいと思うのです。ですから、ぜひそのようなところを活用していただいて、子どもたちの本音を引き出していただくようにお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"ゆきた委員","kind":"質問","question":"１点だけ、条例制定に当たって、子育て支援団体にヒアリングとありますが、様々な事情から、自ら声を上げることが難しい子どもの意見、例えばヤングケアラーなどがあると思うのですけれども、具体的にどのようなヒアリングをしていくのか、現時点で分かる範囲でお聞きしたいと思います。","respondent":"柴田子ども施策連携担当課長","answer":"幸いに区の中にはヤングケアラーの支援チームがあったりしますので、そういった方々のお力も借りたいと考えてあります。そういった知見を活かしながら、子どもたちにとってよい形でヒアリングができればと考えています。","id":"exchange-043"},{"speaker":"ゆきた委員","kind":"提案","question":"提案ではなくて恐縮ですけれども、幅広く連携していただいて、実効性のある計画づくりになってほしいと求めました。これは要望で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"高橋（し）委員","kind":"質問","question":"どうやってその権利を、そういった部分についてのお考えと、殊更きちんと進めていくのかということがあります。３つ目は、その責務について守るべきとなっているので、３つお願いします。","respondent":"柴田子ども施策連携担当課長","answer":"名称を知っているというだけでも、入り口としては大変重要かと思いますので、そういった視点を持って検討してまいります。いずれにしても、そのような形で、責務についても定めていきたいと考えています。","id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今独立性というお話がありましたので、ぜひその点を留意して、公的な第三者機関的な形でしっかりとやってほしいと求めました。もちろんいろいろ調べて課長のほうがお詳しいと思うので、ぜひ区民の方々に知っていただけるような条例にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"山本副委員長","kind":"質問・要望","question":"令和８年３月の予算特別委員会において、学習用タブレットを活用して、できるだけ幅広く意見を聞くことを要望いたしました。どのような形で想定されていらっしゃるのでしょうかということで、何か計画があれば教えてほしいと求めました。","respondent":"柴田子ども施策連携担当課長","answer":"初めのアンケートの進め方なのですけれども、中学校、対象の子どもたち全員から回答が欲しいなということで進めているところです。そしてそのキャラクター自体も子どもたちが考えてつくって、そういったものがすごく有効なのかなというように見ているところです。","id":"exchange-047"},{"speaker":"山本副委員長","kind":"質問・要望","question":"関わってもらうことで、その関心を持ってもらい理解を深めるという取組を、工夫を進めてほしいと求めました。もう１点お伺いしたいのですけれども、ぜひこれを進めていただきたいと思うのですが、今の段階でお考えのところを教えてほしいと求めました。","respondent":"柴田子ども施策連携担当課長","answer":"大人の目線に加えて、区の実態に即したといいますか、区にフィットする形を今後考えていきたいと思っています。現時点ではまだ固まっていないのですけれども、そういった視点で取り組んでまいります。","id":"exchange-048"},{"speaker":"山本副委員長","kind":"質問・要望","question":"ありがとうございました。おっしゃられたように、ぜひ子どもの視点で、そして子どもの声をしっかりと受け止めて、正しい評価ができるように進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.30bu.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":38,"characters":50343,"voices":142}},{"id":"r08-20260630-5","meetingId":"r08-m0708","date":"2026年6月30日","dateIso":"2026-06-30","committee":"総務委員会","time":"午前10時00分～午前11時42分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"説明に入ります前に、各所管委員会における審査結果","agenda":"説明に入ります前に、各所管委員会における審査結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回の補正の考え方、ポイントがあれば伺いたいと思います。見ていると、区は下げるということになっていますけれども、拡充ではなく区が引き下げることになった理由を伺います。","respondent":"加島財政課長","answer":"今回の第２号補正予算の考え方についてですけれども、６月補正で新たに特定財源を受け入れ、制度の充実を図っていくものです。それから、都が定めている認証保育園の保育料の上限額に合わせたものと、区のほうでは想像しているところです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"預かり保育のところは、結果的に区民としては変わりがないということになるのか伺いたいです。","respondent":"加島財政課長","answer":"預かり保育とはまた別の話になります。国が引き上げた分を都が引き下げた、区民の方がこれまで受けられていた補助が少なくなってしまったとか、そういったことではございません。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問・要望","question":"その点についてどのようなご見解を持っていますでしょうか。私はこれも都や国にもっと働きかけていただきたいと思うのですが、その辺は区としてどのような働きかけをしているのか尋ねました。","respondent":"加島財政課長、藤村企画課長","answer":"５月の補正予算におきましても、全世帯を対象とした電気・ガス料金の緊急支援ということで、暮らしを応援するための物価高騰対策を実施いたしました。財源は限られておりますので… もう１点のほうになりますけれども、病児保育ですとかお子さんの具合が悪くなったときの対応につきまして、そういったところを活用して訴えかけてまいりたいとは考えております。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり、街のにぎわいもこういう人たちが存在しなければ、いくら人だけが住んでいても私は街の中、品川区の中は寂しいものになると思います。私は５,０００円でも １万円でも支援すれば、小規模事業主に寄り添うような施策をこれからしていっていただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"次の第３回定例会がある夏明けまでに、ぜひこの補正予算でも機敏に対応していくことが求められていると思います。いかがか尋ねました。","respondent":"藤村企画課長","answer":"ナフサ不足への対応、今の物価高騰ですとかこういったアメリカとイランの戦争に関する全庁的な支援についてかと思います。企業の方へのご支援につきましては、先だってご説明差し上げているところですけれども。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういうところは経営自体が大きくないですから、融資あっせんと言われてもなかなか融資を受けられる状況かなど、厳しいところも多く伺います。そういう判断がいよいよ迫られているのではないかと思いますけれども、最後に区の見解を伺いたいと思います。","respondent":"藤村企画課長","answer":"中小零細企業への直接支援となるとどういった基準を持ってやるですとか、そういった細かい仕組みづくりも課題になってくることかと思います。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ中小企業のところをしっかり目配りしていただきたいと重ねて要望して、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-02","title":"三木小学校外壁改修その他工事請負契約","agenda":"三木小学校外壁改修その他工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"今外壁工事をすれば１０年間以上は外壁がきれいなままだと思うのですが、ここは建て直しというようなことはないのですか。その辺について、ご見解を説明するよう求めました。","respondent":"廣瀬経理課長","answer":"こちらは、雨漏り等が発生していたほか、避難所機能の維持向上について地域から要望があったことから実施するものです。改築着手時期は未定ですので、まずは予定している改修工事を完了し、施設の健全な状態を維持することが重要と考えていると所管から聞いております。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"ということは、請負契約を既にやっているのに、今、報告事項として提示をされたということですか。体育館のほうは後から防水改修工事ということですけれども、外壁に関してはきれいだということは既にやっている、終わったということか尋ねました。","respondent":"廣瀬経理課長","answer":"工期のほうは、こちらに書かれていますとおり６月から１１月までの工期で、今工事をしているものです。３か年計画というのは、全体で３か年かかるということで、契約自体は個別のものとなっております。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"課長も見られたと思うのですが、それにしては外壁がかなりきれいに見えましたけれども、違うのでしょうか。所管が違うのでそれはあれですけれども、かなりきれいなのですが、それでもやらざるを得ないということか尋ねました。","respondent":"廣瀬経理課長","answer":"今回工事するところは、もちろん手が入っていないところで、新たに６月から１１月までかけてやるというものです。隣の西品川保育園については、把握しておりません。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"３か年計画でやっているということなので、今回は校舎西側の外壁だけですけれども、ほかのところは既にこの２年間でやられたということなのかを伺いたいです。","respondent":"廣瀬経理課長","answer":"３か年工事であり、今年度が最終ということですので、今年度で全て完了ということになります。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"一応何となくスケジュールが出されたような気がします。そうしたことへの影響は特にないと考えていいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-03","title":"令和７年度庁舎使用料等未請求事故","agenda":"令和７年度庁舎使用料等未請求事故","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"調定処理とは何かということも含めて、調定処理を行わなかったのはなぜかというところを伺いたいと思います。原因の２つ目は確認体制が不十分だったということですけれども、今までは特に請求書を送って、確認体制が不十分だったというのはどういう状況なのか。","respondent":"廣瀬経理課長","answer":"過去に同様の事故があったかということですけれども、現在過去３年分につきましては緊急点検を実施しています。職場内においても確認体制ができていなかったというのは、当然に担当者が処理するものと考えていたというところが要因の１つであると捉えております。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"私もこの分野のプロフェッショナルではないですから、３年が妥当だということであればその根拠を説明いただきたいし、そこをご説明いただきたいです。再発防止策を検討してこれでいこうというスケジュールは、誰がどう判断するのか、そこの中身についてご説明ほしいと求めました。","respondent":"廣瀬経理課長","answer":"再発防止策の実施につきましては、基本的には課内、係内で実施をしてまいります。それぞれ、確認者、係長、庶務、予算担当者でチェック、点検を進めてまいりたいと考えております。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"使用料だから経理課のほうでまとめてやるということなのか、伺いたいです。それはそれで、どうして今回の収入未済というものが判明したのか、そこをご説明いただきたいです。","respondent":"廣瀬経理課長","answer":"収入が一部あるということが判明しまして、その時点で洗い出しを行って、本件の未収入の請求が判明したです。庁舎の使用料は基本的に経理課のほうで庁舎の使用許可を出しているので、この品目についてはほぼほぼ経理課のほうが所管しています。","id":"exchange-015"},{"speaker":"松本委員","kind":"確認","question":"対策の打ち方について、その防止策の１つとして再発防止策（１）の①で、調定の作成漏れがないかを確認すると書いていただいています。この辺りは、これで足りるのか尋ねました。","respondent":"廣瀬経理課長","answer":"委員がご指摘のとおり、予算額のみで全てを洗い出せるものでないということは認識しております。具体的に今後毎月の確認というのはこれ以降の（２）の①、②のほうで点検をしてまいりたいと考えております。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"うちの会社でもそうですけれども、また翌年度は同じようなリストがあればそこで発送すればいいわけですから、少し不思議なような気がします。それについて、今の私の疑問に対して、ご意見を説明するよう求めました。","respondent":"廣瀬経理課長","answer":"ほかにはないのかというところですが、先ほどご回答したように現在点検を行っています。そういったところもございまして、今年度も当然なされるべきだろうという中で、チェック体制が働いていなかったところがあったです。","id":"exchange-017"},{"speaker":"須貝委員","kind":"確認","question":"それについても何年か調べていただいて、何も問題がなかったらなかったで確認をして、また報告をしていただければいいのかと思います。事なきを得てよかった結果なのか、後で報告していただければありがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"松本委員","kind":"質問","question":"だったら、月末の調整処理を各所職員が忘れていないかを上長がチェックするということもイメージしやすいのですけれども、どちらでしょうか。この辺りはどうなのか尋ねました。","respondent":"廣瀬経理課長","answer":"一応、こちらに記載されているは担当者の調定処理のうちの一部です。光熱費などは毎月発生するようなものもありますので、請求できているものとできていないものが混在していたという状況です。","id":"exchange-019"},{"speaker":"松本委員","kind":"質問","question":"担当者と書かれていますが、１名の方なのですか。どちらか尋ねました。","respondent":"廣瀬経理課長","answer":"１名の者が担当しております。","id":"exchange-020"},{"speaker":"松本委員","kind":"確認","question":"ここまで申し上げたので、あとは多分経理課のほうで対策を考えていただいて、ただ、同じようなことが起こる可能性はどこでもあるので、これは経理課でのところですけれども、ほかの課でも同様のミスはないかというところをこの機会に確認してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"今日が末ということで、ほぼ納入されているのかを確認させていただきたいです。やはり、そうしたことがない仕事量にしていくということも一つ重要なのかと思うのですが、いかがか尋ねました。","respondent":"廣瀬経理課長","answer":"品川区のほうでデータを確認できるようになるまで若干のタイムラグはあるのですけれども、スタッフの口頭ではその旨は確認しています。それと、本人に過度の負荷がかからないような形で今年度の事務の分担を進めてまいりたいと考えております。","id":"exchange-022"},{"speaker":"つる副委員長","kind":"確認","question":"各委員の質疑で確認できたところと、全体で４科目１１件ということで、分かったことが出納閉鎖でということだと思います。そもそも、まず同月のものの処理として今回失念となっているのか、それとも複数月にまたいでいるいわゆる失念であったのかを説明するよう求めました。","respondent":"廣瀬経理課長","answer":"本件は様々案件が交ざっているのですけれども、同月ではなく複数にわたっているものです。","id":"exchange-023"},{"speaker":"つる副委員長","kind":"質問","question":"複数ということで、そうするとそれはそれで別にそうですかと言って忘れてしまうことはありますと先ほどの質疑の中であったわけですけれども。でも、そもそもさっき言葉の意味を説明してくださいとご発言があった調定処理、これは何に定められているものなのかを説明するよう求めました。","respondent":"廣瀬経理課長","answer":"調定処理自体は品川区会計事務規則に定められているものと認識しております。","id":"exchange-024"},{"speaker":"つる副委員長","kind":"確認","question":"この報告でいろいろ確認する中では、法令で定められている必ずすべきものということで、 フローがあるわけですよね。今回の４科目１１件の内容からすると、経過だけではない部分でのチェックというのはできないものですか、できるものか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"つる副委員長","kind":"質問","question":"そういうようなチェックと言うのですか、対債務者の事業者とのそういったやり取りの中のコミュニケーションと言いましょうか。そこら辺は今後どうやっていくのか説明を求めました。","respondent":"廣瀬経理課長","answer":"既に誠意を持って説明をいたしまして、全十何事業者ともご理解をいただいて、お支払いの意思を確認しています。それに伴い、再発防止策にも取り組んで参るのですけれども、お互いの中で請求の支払い漏れがないようにはしてまいりたいと考えております。","id":"exchange-026"},{"speaker":"須貝委員","kind":"意見","question":"それが今回は出なかったというのは、 私は非常に残念だと思います。我々は信用でやっていますので、長年そういうふうにきちんと払っているならば、やはり僕は一言経理課にあってほしかったと希望的に申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"中塚委員","kind":"確認","question":"１点だけ。そこだけ最後に確認したいと求めました。","respondent":"廣瀬経理課長","answer":"全庁的なところということですけれども、今回は会計管理者と企画部のほうで連名で全庁的な注意喚起は行っているところでございまして、各課で同じような確認体制は各課の体制によってですが、含まれているものと考えております。","id":"exchange-028"}]},{"id":"topic-04","title":"ありがとうございます。 それでは、正副委員長でまとめさせていただきます。 次に、⑶その他","agenda":"ありがとうございます。 それでは、正副委員長でまとめさせていただきます。 次に、⑶その他","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"その詐欺バージョンが今流行っているので、そこは相手方に対して少し配慮をして、間違いなく品川区だとわかるように。どういうふうに証明したらいいか分からないけれども、今は電話がかかってきたり封書が来たりして、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"つる副委員長","kind":"意見","question":"そうなんだというところでエリアにメッシュをかけて、捕捉していくみたいなことがあるのではないかと思います。還付しますとなって、それに乗じていいチャンスだと、まき餌みたいになってしまうという可能性にも注意しながら、７月の報告を待ちたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"松本委員","kind":"質問","question":"職員の人事記録に関する規則第２条がこれまで根拠だったというか、多分この規則は結構ほかの区も同じようなものしか定めていないと思います。その上で、これまでは職員の人事記録に関する規則の第２条というところで、規則をつくられたのかというところを伺ってもよろしいか尋ねました。","respondent":"横田人事課長","answer":"職員を他団体へ派遣する場合における個人情報の適正な取扱いについて、必要な事項を規定いたしました。その中で、派遣時に提供可能な保有個人情報ですとか、要配慮個人情報の提供には本人同意を有するなどを規定いたしました。","id":"exchange-031"},{"speaker":"松本委員","kind":"質問","question":"派遣した先のほうの取扱いについて、どういうふうに行政としては対応いただいていますか。派遣するときに、こちらが派遣先でも規則を定めてくださいなど、いろいろと伝え方はあると思うのですけれども、現状そこはどうなっているのか尋ねました。","respondent":"横田人事課長","answer":"細かくはまだ派遣先と調整できているところではないのですが、一応今後の取扱いといたしまして、 区が提供された情報について利用目的外の利用を禁止するとか適正な管理と保護、そういったことをうたって先方にもご理解いただくように努めてまいります。","id":"exchange-032"},{"speaker":"松本委員","kind":"意見","question":"分かりました。先ほど申し上げたように、ネガティブにではなく今後よりプラスになるような配慮としていろいろと考えてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.30so.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":27,"characters":31953,"voices":106}},{"id":"r08-20260701-21","meetingId":"r08-2t","date":"2026年7月1日","dateIso":"2026-07-01","committee":"子ども若者支援・共生社会推進特別委員会","time":"午前10時00分～午前11時26分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"子ども若者支援・共生社会推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"せお委員","kind":"確認","question":"確認なのですけれども、３番の利用認定申請数です。例えばある園では、後半は使えませんという話になると思ったのですけれども、そういう実態はどうなのか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"現時点におきましては、今回この事業を実施しようとしている５７施設でいくと、現在は対応することが十分に可能と考えております。１年間通じて需給はしっかりと注視していきたいと考えておりますけれども、ニーズに対応できるような体制を整備していきたいと考えています。","id":"exchange-001"},{"speaker":"せお委員","kind":"意見","question":"まだ始まったばかりですので、大変ですけれども、そこら辺は適宜様子を見ながら調整していただけたらと思っています。はこれで終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"澤田委員","kind":"質問","question":"それこそ第２、第３を決めなくても、その都度柔軟に対応していただける考え方があるのかどうか説明を求めました。","respondent":"佐藤保育事業担当課長","answer":"今ご質問いただきました第２、第３希望園を選ぶことが可能なのかにつきましては、可能というように対応させていただいてあります。都度、一定程度利用されるということでございましたら、ほかの園をご登録いただくのは可能となっております。","id":"exchange-003"},{"speaker":"澤田委員","kind":"質問","question":"２歳児は６人、３歳児は１５人を見られる中で、説明を求めました。","respondent":"佐藤保育事業担当課長","answer":"一般型の場合は、もう枠を固定して運用する形になっておりますので、その枠に対応した保育士が各園に配備されているものです。余裕活用型は、定員分の保育士は毎月必ず配置されておりますので、どちらの形態にとっても保育士の確保はできていると考えております。","id":"exchange-004"},{"speaker":"澤田委員","kind":"確認","question":"確保できているということで安心しました。最後ですけれども、どのようにこれを周知しているのかも確認したいと求めました。","respondent":"佐藤保育事業担当課長","answer":"今年５月頃に特別な広報誌を作成させていただきました。子育てアプリといったものでの周知、ホームページでの周知などを行って、幅広く皆様に知っていただきたいと考えております。","id":"exchange-005"},{"speaker":"澤田委員","kind":"質問","question":"子育てアプリもしっかり活用してくださって、うれしいと思っています。出産を控えている方とか、これからの子たちに対してもしっかりと周知していただけるとうれしいと思いますが、いかがか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"今様々なご助言をいただきまして、出産を控えた方へのアプローチはまだ足りなかったと思いましたので、そうしたご助言を活用させていただきながら対応していきたいと思っています。","id":"exchange-006"},{"speaker":"おぎの委員","kind":"質問","question":"第３希望まで受け入れていただけるというお話もありましたが、実際は自分の家に一番近いところから想定して希望されている部分があると考えています。地域によって数字に大分偏りがあるような気はしているのですが、この辺りは、ニーズに対してばらつきとかはどのような感じなのか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"地域の偏在については、我々も課題と思ってあります。偏りがあるところが、東大井・八潮地区が少ないので、ここにある園には今後も継続して積極的なアプローチを行っていきたいと思っています。","id":"exchange-007"},{"speaker":"おぎの委員","kind":"質問・要望","question":"お母さんたちの生活、あと園児の数を見ながら進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"モデル事業を含めると４年目になると思うのですけれども、これまでの３年間と今年度の２か月の状況を見て、当然実施件数は全然違うし、乳児も違う、保護者も年々変わるわけですが、ご意見やご感想など、モデル業を含めて改善点として今年度とか、大きな特徴、変遷をまず説明を求めました。","respondent":"佐藤保育事業担当課長","answer":"利用上限が１０時間と定まっていたのですけれども、試行的事業の実施を通じまして、最適な時間設定ができたと考えています。お気持ちとしても、体制を整えて４月から実施する必要性があるというのをしっかりと認識して事業実施することができたと考えています。","id":"exchange-009"},{"speaker":"つる委員","kind":"確認","question":"数字的な確認で、在宅で子育てしている中でのゼロから２歳児は、在宅子育ての９割ぐらいの人数のイメージだと思っています。大体 ６,２００人いて、そのうちゼロから２歳児が５,４００人で９割近くと思うのですけれども、現在の状況を説明するよう求めました。","respondent":"佐藤保育事業担当課長","answer":"令和６年度は ６,２２５人の人口の中で、保育施設等を利用されていらっしゃる方が４,３３９人、利用率は７０％程度となっているものです。","id":"exchange-010"},{"speaker":"つる委員","kind":"意見","question":"そうすると、さっき項番３の利用認定申請数の４４１人というと、６００分の４４１というイメージだと思います。今実態としてどういう把握があるのか、残りの２,４００人を区としては今どんな感じで把握し、逆に言うと課題があるのかもしれませんとの意見を述べました。","respondent":"佐藤保育事業担当課長","answer":"子ども家庭支援センターですとか、保健所と連携して、行政機関とのつながりをしっかりと持っていく。こうした取組もずっと行ってありますので、継続していきたいと考えております。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"そういったところにサーチライトを当てて、一人一人を見逃さない施策全体の構築を今後もやってほしいと求めました。誰でも通園で受け入れるのは大体何メートルに１園とか、児童センターだったら８００メートルに１つで、今どういう状況なのか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"現時点におきましては、ニーズに対して対応できている認識です。様々な事業者へのお声がけ、または公立の施設での開始なども含めまして、幅広く検討していく必要性があると考えております。","id":"exchange-012"},{"speaker":"つる委員","kind":"意見","question":"そうすると、年間で見ても、年度で見ても、１年度で５回ぐらいの利用ということです。月３０時間だから、もう少し余裕があって使えますというイメージですよねとの意見を述べました。","respondent":"佐藤保育事業担当課長","answer":"これも昨年度まで実施してきた試行的事業での平均の利用時間などを参考に設定しているものです。委員がお話しいただきましたように、１日６時間、５回のような形で利用される方を想定したものです。","id":"exchange-013"},{"speaker":"つる委員","kind":"意見","question":"プレス発表ですとか、今日の資料も含めて、３０時間になっています。どちらが正しいのかとの意見を述べました。","respondent":"佐藤保育事業担当課長","answer":"申し訳ございません。事項別明細については、今手元に資料がございませんので、把握していないのですけれども、３０時間の上限で実施させていただいてあります。","id":"exchange-014"},{"speaker":"つる委員","kind":"意見","question":"事項別明細の１１３ページにある事業の概要の中の内容②の中に、区は都補助を活用し、月４８時間まで拡大実施となっているのです。それで今３０時間という話で、ここはどうでしょうとの意見を述べました。","respondent":"佐藤保育事業担当課長","answer":"大変申し訳ございません。改めて確認させていただきたいのですけれども、３０時間が正しいというものです。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問","question":"３年間でいろいろあったと思うのですけれども、その月の事業者としての収支、ここはきちっと入りがあるということです。要するに確保しなければいけない、アイドリングしていかなければいけないと思うのですけれども、どうなっているのか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"まさに委員がお話しいただきましたように、実施していただいている施設への補助は、区としても非常に重要な点であると考えています。国の制度では、月額で一定額を実施していただいて、加えてお預かりの時間数に応じた補助額を公定価格に上乗せする形で実施しています。","id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"実績としてキャンセルになってしまって、通園がないけれども、利用があったものとして公金を支出されるような形になる。これはどうなのか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"申し訳ございません。利用実績がない場合のお支払いは実施していないのですけれども、時間で急なキャンセルの場合はお支払いするというものがあったと認識しています。","id":"exchange-017"},{"speaker":"松本委員","kind":"質問","question":"お支払いはなくて、当日キャンセルだと区からお支払いがあるのだと、何となくイメージします。施設としても、売上げが下がってしまう状況もあり得ると思うのですけれども、この辺りは区としては何か対応されているのか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"現在２か月の事業実施に当たって、そうしたご質問等を法人の方からいただいたことはない認識ですが、可能性としては十分あり得るところがあります。","id":"exchange-018"},{"speaker":"松本委員","kind":"確認","question":"最初のところからお伺いしたいのですけれども、この制度は、先ほどの空き枠を使う制度ともう１つの制度があるとお話がありました。柔軟事業ではなくて定期利用を原則とした理由をお伺いできればと思うのと、例外も一応あり得るとは思うのですけれども、ここはいかがか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"同じ保育士の環境の中でお子さんが過ごされることが良いだろうと考えたことと、事業実施していくのが非常に不安であるというお声もありました。","id":"exchange-019"},{"speaker":"松本委員","kind":"確認","question":"これは事実かどうかの確認はしていないですけれども、どういうことかというと、１回の利用時間がすごく限られている。受入れ可能時間が９時から４時になっていたり、このあたりの受入れ可能時間はどういう縛りになっているのか、ここは何かルールがあるのか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"１日ごとの実施時間についてです。実際に運用される保育園の皆様の運用形態、また職員配置など、そういった様々な状況の中で設定していただいている状況です。","id":"exchange-020"},{"speaker":"松本委員","kind":"確認","question":"これを見ながら、私も実際のマイナポータルの中に入っていくと、自分の情報を書かなければいけない。あくまでホームページ上で確認している範囲ですが、保護者の方たちの参考になると思うのですが、いかがか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"実際の保護者の方の声をいただいて、大変ありがたいと思ってあります。ホームページ上で、いただいたご助言を活用しながら、区として対応できることがどういったものなのか改めて検討していきたいと考えています。","id":"exchange-021"},{"speaker":"松本委員","kind":"提案","question":"保護者の方たちの不満を伺っていると、文字情報がたくさんあるので、全部を読み込むのはなかなか大変というお話をよく伺います。これは最後に提案をさせてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"せお委員","kind":"意見","question":"先ほどおぎの委員から、対応はその障害によりますけれども、その園児に対して１人つけなければいけない場合もあると思うのです。そういった対応はどうなっているのかを説明するよう求めました。","respondent":"佐藤保育事業担当課長","answer":"現在区は特殊な対応が必要なお子さんを預かりいただいた際に、そのお子さん専任でつく職員を雇用した際の人件費の補助を行ってあります。本制度につきましても、 事業者の方からそういったお問合せがありましたら、柔軟に対応していきたいと考えています。","id":"exchange-023"},{"speaker":"せお委員","kind":"質問","question":"ゼロ歳から２歳の頃は不安がすごくいっぱいあったので、障害があるお子さんの保護者にも伝わるような周知の仕方をぜひお願いしたいと思っています。そういったところにどう関わってくるのか、昨年の答弁を聞いていて感じていたので、もし分かれば説明を求めました。","respondent":"佐藤保育事業担当課長","answer":"在り方を検討していく中で、定員に対してどれだけの利用があるのか、非常に大きな要素の１つであると思います。そうするとそのニーズに応えるだけの供給は必要となるのだろうと、保育園・幼稚園の在り方を検討していく上で影響のあるものと考えています。","id":"exchange-024"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"今までの委員の質疑の中で確認させていただいたことがあるのですが、改めて東京都、品川区が誰でも通園制度を行う目的を教えてください。それと、もし差し支えなければ、８月に新たに２施設が開園ですが、どの地域でどの園なのかを公表いただけるのであれば教えてほしいと求めました。","respondent":"佐藤保育事業担当課長","answer":"続いて、８月より新たに実施予定の２施設です。続いての施設が、花房山目黒駅前保育園３３３という施設でございまして、こちらは五反田地区です。","id":"exchange-025"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"５９施設になった暁には、そういうのも少し入れていただくといいと思いますので、 ぜひそれは要望させてほしいと求めました。いかがか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"今年度につきましても、こうした取組はしっかりと継続していきたいと考えています。今、実は用意しておりまして、今後速やかにホームペー ジ上にマップを掲示していきたいと考えています。","id":"exchange-026"},{"speaker":"新妻副委員長","kind":"質問","question":"他自治体に先駆けて５９施設まで広げていただいているのは、どうしても地域偏在があって、入れなかった方が多くいた地域であります。なぜここが少ないのかと、区が事業者側にどうしてできないのかという把握はされているのか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"委員からお話しいただきましたように、園数自体も非常に少ない地域であることから、ほかの地域に比べて数が少ないと推測しています。この数を課題として認識しておりますので、こうした偏りを少しでも解消できるような取組は引き続き実施していきたいと考えております。","id":"exchange-027"},{"speaker":"新妻副委員長","kind":"質問","question":"最後に１点だけ、オアシスルームとの関連についてお聞きしたいのですけれども、ここは５００円という有料の施設になっています。誰でも通園を使える園の開設によって、オアシスルームの利用者が減ったとか、そこの利用者の使い分けをどうされているのかお聞きしたいと思います。","respondent":"佐藤保育事業担当課長","answer":"目的や利用形態等が確かに一定程度重複する部分はあると考えていますが、より生活の支援ということ、成長に関しての環境の整備という側面があります。こうした違いがあると考えております。","id":"exchange-028"},{"speaker":"つる委員","kind":"質問・要望","question":"さっき言い忘れて、項番１の（６）の一般型の括弧内にある在園児と合同でやっているところと専用室について数字で求めていないかもしれない。","respondent":"佐藤保育事業担当課長","answer":"一般型の在園児合同型と専用室独立型の分けです。在園児合同型が６施設、専用室を設けているのが２施設、合わせて合計８施設となっております。","id":"exchange-029"},{"speaker":"つる委員","kind":"質問","question":"項番１の（４）のさっきの３００円ですが、区内の施設については、区は利用者からお金を取らずに無償、これが区です。その支払いの精算方法はどうなっているのか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"区外の施設になりますと、利用料金を国としては徴収するようにとなっていますので、一般的には費用がかかるものになってあります。一旦お支払いをしていただきまして、後に品川区に対して補助金の申請をしていただくと、そちらの費用をお支払いするような内容となっております。","id":"exchange-030"},{"speaker":"つる委員","kind":"質問","question":"３０２円となるから、どうなのか、２７５円設定が分からないので教えてください。２７５円×２万８５６時間×１２か月で、予算の数字が出ているのですが、３００円ではなく ２７５円にしている意味を説明するよう求めました。","respondent":"佐藤保育事業担当課長","answer":"こちらは国から１日２,２００円を上限に利用料金を取ることができると伝えられてあります。国としては３００円程度という言い方をされておりまして、予算書等では一応８時間で割った２７５円で計算させていただいているものです。","id":"exchange-031"},{"speaker":"つる委員","kind":"質問","question":"勉強になりました。これまでの３か年度も含めて、今年度２か月の状況を、説明を求めました。","respondent":"佐藤保育事業担当課長","answer":"多胎児の方のご利用などの実績につきましては、大変申し訳ありません。手元にデータがなくて、どのような利用実態になっているかは把握してございません。","id":"exchange-032"},{"speaker":"つる委員","kind":"質問","question":"誰でも通園の中で３か年度の実績、経済的な部分は、尺度がすごく違うのだろうと思うのです。品川区は３年間のモデル実施の実績があるので、多胎児の対応、それから障害児の対応のアジャストはどんな印象があるのか説明を求めました。","respondent":"佐藤保育事業担当課長","answer":"区としても検討はしていないですけれども、今後制度を実施していくに当たりまして、様々な声をしっかりと拾っていかなければと考えています。そうしたお声があるのか、ニーズ等をしっかりと注視しながら対応していきたいと考えております。","id":"exchange-033"},{"speaker":"つる委員","kind":"質問","question":"横を見るのは２３区ぐらいだと思うのですけれども、所管としても、その辺は積極的な検討をお願いしたいと思います。３０時間だろうという十何時間の余裕が、そこを次年度に生かせるという期待もあったものですから、あえて特別委員会の場で言わせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-02","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"せお委員","kind":"質問","question":"先ほど冒頭でご案内があった今後の調査日程について質問する機会がなかったので、この場合、結局入ってくるのかこないのかというところです。議会運営委員会でも書いてくださっているのですけれども、ここには入っていなかったと思うので、そこら辺がどうなったのか説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"つる委員","kind":"質問","question":"関連となると、当然全体の年間の予定を出してくる。ただ、その方への支援はどうなのですかと質疑したときには、常に残りの委員会全て所管の課長に出席をお願いするという理解でいいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"つる委員","kind":"確認","question":"そうすると、この特別委員会の冒頭で示された中にそういう明記があって、 あのとき委員長に確認して、含まれていますという見解があったのです。明確に確認して、その際に明確に見解として述べるべきだったと、これはあえて申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.07.01kw.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":20,"characters":24253,"voices":85}},{"id":"r08-20260701-20","meetingId":"r08-2t","date":"2026年7月1日","dateIso":"2026-07-01","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午前10時00分～午後０時05分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"このデジタルプラットフォームを幾つか確認、教えていただきたいのですが、これはプレス発表等の中でどのようにご説明をされたのか。当然、意見の聴取はしないといけないと思うのですが、この設問の設定についてはこの委員の方がどのように関与されるのかということを説明するよう求めました。","respondent":"井添政策推進担当課長","answer":"特に次年度に向けて令和８年度からその点をアップデートするというご説明をさせていただきましたが、詳細については本日のご説明が初めてになるです。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"デジタルプラットフォームを活用してというところは今日初めて伺ったという認識で質問したいと思います。前提ではないというお話がありましたけれども、フラットに区民が意見を言えるようなプラットフォームになるのかどうか、確認をさせていただきたい。","respondent":"井添政策推進担当課長","answer":"行政評価委員会を実施していく中で業務支援の委託を入れておりまして、こちらが委員の謝礼が合計１８万円、それから業務支援委託が５００万円。できる限り区の内部の職員で実施できるところは内製化を図りまして、昨年度、こちらは減額をするように努めているところです。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今回、それはほとんどの予算がそこに使われているということは確認させていただきましたが、それでも内製化を図ったのだというところの説明でした。これからやる事業ですから、いかがか尋ねました。","respondent":"井添政策推進担当課長","answer":"それから区民意見を募集した後に２回実施してまいりますが、１０月に実施する前にも９月の段階で、いただいたご意見はしっかりと行政評価委員会に伝えてまいりたいと考えております。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その職員というのはどういう職員の方が入られるのかということについても伺いたいと思います。これも８月いっぱい、１か月間の期間に意見を寄せてもらうということになっていくのか、その点についても伺いたいと思います。","respondent":"井添政策推進担当課長","answer":"アドバイスをいただくような役割を担っていただきたいというふうに考えておりますので、４名で構成しております。まだ検討中の段階ではありますが、９月の頭までとか、少なくとも８月の１か月間は丸々募集期間に割けるようにしてまいりたいと考えております。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"区民が意見を出せるよという、そういう形でぜひしていただきたいなと思うのですけれども、その点を伺いたいと思います。評価というと、そういうところも入っていくのか、その点についても伺えたらと思います。","respondent":"井添政策推進担当課長","answer":"一定のハードルがあるかと思いますので、アカウント登録していただく工夫については引き続き検討をしていきたいというふうに考えているところです。回答ができるようにしておりますので、そちらでできる限り多くの方から意見を募集できればというふうに検討しています。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうプラットフォーム、全区民向けにお知らせはされるということでいいのかという確認をさせていただきたいのと。その点だけお願いします。","respondent":"井添政策推進担当課長","answer":"できるだけ多くの方にご参加いただけるような工夫をしてまいりたいと考えております。しなトークでアカウント登録の登録者を増やす工夫についても関係各連携しながら検討してまいりたいと考えております。","id":"exchange-006"},{"speaker":"まつざわ委員","kind":"質問","question":"しなトークだけではなくて、アンケートとか、ああいうのも含めてやっているものなのですか。今回のこの５項目ですね。","respondent":"井添政策推進担当課長","answer":"そのしなトークの仕様の中で選択式のアンケートと、そちらを両方活用して、しなトークの中でアンケートも含めて実施をする予定です。この５事業につきましては当然、これまでも実施してまいりました事務事業評価でも引き続き内部の評価というものは今年度も実施する予定です。","id":"exchange-007"},{"speaker":"まつざわ委員","kind":"質問","question":"この５事業をこれを見直しを左右する、何というのですか、あまり多くとは言えない意見に左右に反映されるというのはどうなのかなというのがあります。少なくとも結局する必要があるのかなと私は思うのですけれども、そこを説明するよう求めました。","respondent":"井添政策推進担当課長","answer":"できるだけ多くの区民の方から意見を募集できるような工夫というのをこのデジタルプラットフォームの中でも検討したいと考えていますし、周知の方法。その実施状況、実績をよく見まして、検討して次年度以降のそういった対策にも生かしていきたいというふうに考えております。","id":"exchange-008"},{"speaker":"まつざわ委員","kind":"質問","question":"削減と廃止というのはしないではなくて、それも検討していくべきかなと思っているので、引き続き教えてください。それと同じでＤ Ｘもなのですけれども、ＤＸの利用回数というのか。","respondent":"井添政策推進担当課長","answer":"当然、費用対効果の面なども区民の方にご意見を伺いながら、見直し等も含めて検討を進めてまいりたいと思います。今後、どういった観点で次年度の予算ですとか、今後の政策に反映していくかということは検討してまいりたいと考えております。","id":"exchange-009"},{"speaker":"えのした委員","kind":"意見","question":"この対象の５事業がちょうどそこの８月までに実際あるのであれば、７月、そういった事業と一緒に何か周知する取組をお考えなのか。８月までにスマホ教室とかやっていれば、スマホ教室で教えつつ、何かそういった形でつなげる取組をお考えではないのか説明を求めました。","respondent":"井添政策推進担当課長","answer":"例えば、あとはアンケートなどをするような場合には合わせてご案内ができないかどうかといったところは今検討をしているような段階です。本評価対象事業以外のところでも例えば、できる限り広く周知ができるような工夫を検討してまいりたいと思います。","id":"exchange-010"},{"speaker":"えのした委員","kind":"意見","question":"ぜひそういった広めていく取組も進めてほしいと求めました。３分以内とか、また、そういったしなトークのアカウントの登録者数を増やすような取組というのもお考えかどうか聞かせてくださいとの意見を述べました。","respondent":"井添政策推進担当課長","answer":"実績等踏まえて次年度以降のそういったノベルティなども含めて次年度以降の対応については検討してまいりたいと思います。現在検討中の内容としましては、そこで回答までつながらないようなケー スも出てくるかと思いますので、所管課含めて検討している段階です。","id":"exchange-011"},{"speaker":"こんの委員","kind":"質問","question":"この５つの課題は課題として大事なのですけれども、これ、どうでしょうか。広く皆さんから意見をいただくのであれば、そうした課題も選定していくというのは大事であると思うのですが、いかがか尋ねました。","respondent":"井添政策推進担当課長","answer":"その上で、委員がおっしゃったような区民のほうからより重要だと認識するような事業も取り入れるような工夫について、検討してまいりたいと思います。","id":"exchange-012"},{"speaker":"こんの委員","kind":"質問・要望","question":"そういう事業になってほしいというのが区民の願いだと思いますので、ぜひそうした視点を持って今後、広くお聞きほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"山本委員","kind":"提案","question":"そして去年の一般質問でも要望をご提案させていただきまして、今回、これまで要望してきたことが一つ前に進んでいるのかなということでまず。例えば、これは結構やり方がどうなるのかなというところがありますので、そういったところをどのようにお考えかというのを説明するよう求めました。","respondent":"井添政策推進担当課長","answer":"１点目の選定基準や事業の選定の部分につきましては、次年度以降、そういった視点も含めて検討してまいりたいというふうに考えております。","id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"各項目１００件、意見を集めるということでぜひ周知をしていただいて、広く意見が集まるようにしてほしいと求めました。変えていくというのはとても大事なことだと考えていますので、この取組に期待しておりますので、どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"鈴木委員","kind":"質問","question":"委員会も公開してもいいかなというふうに思うのですけれども、議事録が公開されるにもかかわらず、委員会が公開されないというののその理由というのは何かあるのか尋ねました。","respondent":"井添政策推進担当課長","answer":"まずは委員の皆様に忌憚のないご意見をいただく必要があるというところで非公開としています。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問・要望","question":"議事録は公開されるということですので、忌憚のない意見というのは公開されていたら忌憚のない意見にならないかということには、私はならないのではないかなと思いますので、ぜひともこれは公開の方向も含めてご検討いただけたらというふうに、要望をさせてほしいと求めました。","respondent":"西澤ＤＸ戦略担当部長、與那嶺デジタル推進課長","answer":"令和８年度も東京都の事業である障害者向け・高齢者向けスマートフォン普及啓発事業との連携も継続して推進してまいります。続いてデジタル課長から説明になります。 データアナリストと協働し、データと地図を掛け合わせて政策に活用する「地図×データワークショップ」を実施し、１５名の職員が参加いたしました。私からの説明は以上です。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"幾つか質問させてほしいと求めましたが、まず、全体の話をお伺いしたいと思います。全体の３つの区分、それから１２項目の中で順調に進んでいる区分、全体からお伺いしたいと思います。","respondent":"西澤ＤＸ戦略担当部長","answer":"昨年、先ほど説明しましたＡＩを活用といったところが進んでおりまして、こちらに関しても徐々に徐々に進んでいるかなと思っています。それが例えば、ご意見をどう吸い上げるかとか、そういったところを考えていきたいというふうに思っております。","id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"理解をした上でぜひ、地域ＤＸ、地域の皆様の課題解決につながる取組をＤＸで進めていただきたいということで要望しております。これ、意見が集まりやすいのではないかとか、これをやってみての投稿件数を含めての結果に対する受け止め等教えていただきたいと。","respondent":"與那嶺デジタル推進課長","answer":"やはりまだまだニーズはあるのかなというふうには我々認識していますし、そこの事業についてはしっかりと進めていくものというふうに考えてあります。","id":"exchange-019"},{"speaker":"山本委員","kind":"提案","question":"ご提案します。それを解決につなげることができると思うのですけれども、この６１件の相談事項というのは庁内でご共有ってされているのか尋ねました。","respondent":"西澤ＤＸ戦略担当部長","answer":"１点目のＤＸ相談窓口の内容が庁内で共有されているかという点についてになりますが、それを庁内報で掲載するといったことは実施しております。はＤＸアワードでエントリーしてもらうとか、そういったところで周知して横展開を広げていきたいというふうに思っております。","id":"exchange-020"},{"speaker":"山本委員","kind":"質問・要望","question":"そういうよい取組があっても奥ゆかしくて参加されないというか、それはデジタル推進課のほうでよいものはぜひ横展開をしてほしいと求めました。最後に項番１２の「ＥＢＰＭの推進」のところなのですけれども、ここがちょっと前回、現状をどう捉えていらっしゃるかというのを説明するよう求めました。","respondent":"西澤ＤＸ戦略担当部長","answer":"データの中からどう課題を見つけていくかといったようなアプローチをデータアナリストと一緒に考えていくようなワークショップを実施しております。","id":"exchange-021"},{"speaker":"山本委員","kind":"質問・要望","question":"これから伴走支援が始まるということで、ぜひ個別の支援をして課題解決につなげてほしいと求めました。期待しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"こんの委員","kind":"質問","question":"大きく２点伺いたいと思います。１点、この点についてお伺いしたいと思います。","respondent":"西澤ＤＸ戦略担当部長","answer":"紙申請となると、取り違いが結構起こってしまうので、電子申請を使っていくことがミスを一番少なくするポイントだというふうに考えております。","id":"exchange-023"},{"speaker":"こんの委員","kind":"質問","question":"それは必要なので、それとともにその中で起きるミスも未然に防げるような工夫もＤＸの中でしたらどうですかということを申し上げました。そもそも、今品川区で移行したもの、さらに特定移行支援システム、これ、どういうものなのか、そもそもの特定移行支援システムをまず説明を求めました。","respondent":"西澤ＤＸ戦略担当部長、與那嶺デジタル推進課長","answer":"起こってしまうところがあって、そういったプロセスを設けていくことによって未然に防げていくということはできるかなと思っているのです。そういったところも含めて検討、推進していきたいというふうに思っております。それにどんどん対応しなければならなくなったというところもあったので、実際には７年度末までに全てを完了したというわけではないのです。","id":"exchange-024"},{"speaker":"こんの委員","kind":"意見","question":"課長がおっしゃったように将来的にお願いしたいので、次はこっちのシステムを見てってしていると、どうしてもミスが起きやすい。ＤＸのほうでお声をかけていただきながら、改善に向けていただけるとありがたいなと思うのですが、いかがでしょうとの意見を述べました。","respondent":"西澤ＤＸ戦略担当部長","answer":"今後、国のほうでも公共サービスメッシュという考え方がございまして、データ連携がうまくできるような仕組みをつくろうとしています。システムの標準化でこういった連携の基盤ができたので、より区民に利便性が高くする、一歩一歩進めていきたいというふうに考えております。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問","question":"ちょっと教えてください。この令和７年から連携開始というところの連携開始の意味をまず説明を求めました。","respondent":"與那嶺デジタル推進課長","answer":"ご質問いただいた東京都高齢者向けスマートフォン普及啓発事業については、東京都のほうが都民の高齢者向けにスマートフォンの啓発事業を行っているというところで、品川区も会場として使っていただいてという形の連携です。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問","question":"そしてこれも１万１,０００円分のポイントを東京都がつける東京アプリ、あと、高齢者。こうしたスマホの購入費助成、今やっていること以上の何かそういった受皿を用意するのかどうか、その辺りを説明するよう求めました。","respondent":"與那嶺デジタル推進課長","answer":"こちら、そこで申請まで行うという形の支援も合わせて実施しているところです。は実際のボリュームであるとか、そういったところを見ながら必要な支援を行っていこうというふうに考えてあります。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問","question":"板橋区なんかも週に３回ぐらいですか、名称は違いますけれども、そういったところでよろず相談的なものを行っている。私的には不十分ではないかなと思うのですけれども、そこについて庁内検討はしたのか、されなかったのか説明を求めました。","respondent":"與那嶺デジタル推進課長","answer":"庁内検討という形で行きますと、そういったところの活用も含めてどう取り組んでいこうかというところは、所管部署含めて検討を行ってきたところです。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう一回確認をしますけれども、これはもう、そういう内容になっているということで確認させていただいていいかどうか。ここについてもそこで何らかの相談受付等をしていただけるのかどうか、ここについても現段階での検討状況を説明するよう求めました。","respondent":"與那嶺デジタル推進課長","answer":"地域センターでのサポートについては、まず、しながわ電気・ガス料金緊急支援事業については、こちらサポート窓口として開設する予定です。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問・要望","question":"いろいろと前向きにご検討、庁内でしていただいていることも確認できましたので、様々な職員のご負担等も考慮の上、ぜひ前向きに進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その次のＤＸ人材の育成のところで、５人中３人が効率化が進んでいると感じているということ、ということなのですか。ということは、それは区としてはどういうふうに捉えていて、理由がどういうことでなぜなのかというふうなところについても伺えたらと思います。","respondent":"與那嶺デジタル推進課長、西澤ＤＸ戦略担当部長","answer":"恐らくコメントなども含めて１人の方が複数の投稿をしているところはあるかとは思うのですけれども、今、数字を持ち合わせていないところです。いわゆる大規模な情報漏洩であるとか、あと… ５段階評価で評価してもらった結果となっておりますので、まず、ここは人数というところではないところになります。","id":"exchange-031"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これは中核市長会の要望書なのですけれども、２３区区長会でも要望したというふうなことでも伺ったのですけれども。そこら辺のところの２３区区長会の要望だったり、品川区のコスト面での状況ということについて伺えたらと思います。","respondent":"與那嶺デジタル推進課長","answer":"そういったところもあって、なかなか当初もくろみどおりにコスト低減が図られた状態ではないというのは実態としています。２３区の状況としてもそこは認識同じでございまして、国からのサポートというところは必要だというところは主張していく次第です。","id":"exchange-032"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そうすると、３割削減できるというふうな見込みだったにもかかわらず、区としてはどれぐらいコストが増えているのか。令和８年度に関しては国のほうとしても対策がどう取られているのかという辺りもお聞かせいただけたらと思います。","respondent":"與那嶺デジタル推進課長","answer":"少なくとも標準化前に活用していたときよりも全体的なコストは今少し上がってしまっているというところはあろうかと思います。国からの支援ですけれども、特定移行支援システムに位置づけられたことによって本来であれば、これも引き続き継続されているという認識です。","id":"exchange-033"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのことも含めて２３区区長会としても要望されているのか、ぜひそれは国のほうに要望もしていただきたいと思うのですけれども、どういうことになっているのか伺えたらと思います。","respondent":"與那嶺デジタル推進課長","answer":"標準化システムの開発に関しての経費については国費が出るという形であったのですけれども、運用コストのほうも増大していくということも踏まえまして、特別区長会といたしましても国に対して運用コストも含めた支援が必要だという形で要望を出したです。","id":"exchange-034"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ国のほうにしっかりと出してもらえるようにということでこれからも求めていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.07.01sd.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":31,"characters":43492,"voices":90}},{"id":"r08-20260702-22","meetingId":"r08-2t","date":"2026年7月2日","dateIso":"2026-07-02","committee":"まちづくり・公共交通推進特別委員会","time":"午前10時00分～午後０時17分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"まちづくり・公共交通推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査の議題に入ります。 本日は、地域公共交通に関することのうち、自転車等交通ルール","agenda":"特定事件調査の議題に入ります。 本日は、地域公共交通に関することのうち、自転車等交通ルール","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"実際この４月からですか、青切符制度が始まって、区内ではどれだけ取り締まられているのか。その数について、区としてはどう見ているのか伺いたいと思います。","respondent":"原交通安全担当課長","answer":"雨で路面がぬれていたですとか、砂が積もっていたといったところでスリップして転倒するというような対応で単独事故が発生しています。は遮断踏切の立入りなど、この３つの対応を中心に、取締りが行われている状況です。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"都が４５.９％ということですと、昨年は品川区が３％低かったということで、区はどのように考えているのか伺いたいと思います。全校でやられているのかを伺いたいのと、大人への講習というのですか、区の取組強化をどういった形でやっていく考えなのか伺いたいと思います。","respondent":"原交通安全担当課長","answer":"冒頭でご説明させていただいたとおり、こういったものを継続して取り組んでいったところ、継続して取り組んでいきたいです。各小学校に対する安全教室の実施ですが、そういった段階で警察と区で連携を取りまして、教室を行っているところであります。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"子どもたちのところでは、いろいろなところでやられているということですが、全校でこの交通安全教室はやられているのかを伺いたいと思います。やはり事故の年齢層を見ても、幅広くどの年代でも事故が起こっているということですので、ぜひそうした啓発を強めてほしいと求めました。","respondent":"原交通安全担当課長","answer":"ただいまご質問で、教育委員会等とも連携いたしまして、ほとんど ３年生の段階で安全教室をやっていただいているといったところで認識しております。これも継続していきたいと考えています。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、小さいお子さんですとか高齢者の方は歩道も走れますよということも含めて周知しながら、事故がないように進めてほしいと求めました。言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"こしば委員","kind":"質問","question":"何か警察のほうにつなげていくということは、特にそういう情報は入っていないということで、その場で安全に規則を守って通行してくださいという指導にとどまるという形か尋ねました。","respondent":"原交通安全担当課長","answer":"指導員自体も警察官との接点を持っておりますので、そこで意見交換をしたりして、各警察署管内の状況などをお伝えしています。指導員につきましては取り締まる資格はございませんので、一件一件、警察に情報提供をするという形では行っていないところです。","id":"exchange-005"},{"speaker":"こしば委員","kind":"質問・要望","question":"ありがとうございました。ぜひ警察とも連携を取って、共有をして、しかるべき対応をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"品川区では自転車活用推進計画を令和６年に定めておりますが、この推進計画を変えていく予定があるのかどうか、まず確認させてほしいと求めました。","respondent":"原交通安全担当課長","answer":"令和６年度に定められました、こちらの活用を推進できるようにというところで、大綱を決めているところです。やはり安全に走っていただくといったところを、こちらの枠組みの中で各種指導、広報・啓発等を推進していきたいと考えているところです。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問","question":"明らかに歩道通行は原則としてはいけないということですから、逆に言うと、車道を走行する際に危険度が増す傾向にある場所があると思うのです。ほかにもまだまだ同様の視点で見直すべき点はあるかと思いますので、ぜひ計画見直しはしていくべきだと思いますが、改めてお伺いしたいと思います。","respondent":"溝口防災まちづくり部長","answer":"令和６年につくった自動車活用推進計画のときと、当時から原則としては、車道を自転車が通行するという形になっております。１２次の交通安全計画の見直しも行っておりますので、そういったものも踏まえて、必要な計画は見直しをしていきたいと考えているところです。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"絶えず状況変化に応じて見直すべきだと思いますが、今回、私は見直す大きなタイミングだと思います。具体的にどういう標識だったらばいいよというのをやはりこういうところに示してあげることも、ぜひ改めてほしいと求めましたが、どうか尋ねました。","respondent":"原交通安全担当課長、溝口防災まちづくり部長","answer":"また標識等の説明といったところでございましたので、細かなそういった区民の方からの質問・疑問等に対しては、丁寧に説明をしていきたいと考えています。 ２メートルの歩行者空間と、歩道であっても自転車が通行できる、そういったことも整備としてはやっているところです。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"ここからはというようなものも、より丁寧に理解していただけるような対応を、警視庁とも連携して対応してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"若林委員","kind":"確認","question":"２ページ目の表の見方ですが、右折時の違いはどういうことなのか確認させていただいて、これは人対自転車ではない事故という意味ですか。という確認と、そこら辺、要するに事故の原因は複数あるよなという思いの中で質問しております。","respondent":"原交通安全担当課長","answer":"やはり対応が複数、複数ある場合は、一番割合として高いものを統計として取っているような状況があります。バイク、自動車等も含みますが、全て車両という認識でお願いしたいと思います。","id":"exchange-011"},{"speaker":"若林委員","kind":"質問","question":"左折時は、後ろから来た車両と接触という説明に今聞こえたのですが、それは理解できないので、もう一回聞きます。１回直進して方向を変えて右に行くというのが自転車ですけれども、一つの信号でそのまま右折して、直進の車とという意味でよろしいのか尋ねました。","respondent":"原交通安全担当課長","answer":"自分の左後方から擦り抜けるような形で来た車両と、巻き込むような形で衝突する、こういった態様が代表的なものであります。やはり２段階右折をしていれば、２段階によらないで右折をしていって、対向車両と衝突といったような態様が代表的なものです。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問","question":"１ページ目の、いわゆる青切符を導入したということは、取り締まる側にとっては取締りがしやすくなるという表現がありました。変えたとしたら、どういうところに着眼しているのか、そこら辺を教えていただければ。","respondent":"原交通安全担当課長","answer":"制服を着用した警備員、責任者１名と活動員２名の３名がユニットとして活動しております。逆走ですとか、区民の方から寄せられる声を参考にして、危険性が高い行為を重点的にお声がけさせていただいているといった状況です。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"できれば自転車を降りて、歩いていただきたいということが一応あるのですけれども、なかなかそうはいかないと。商店街のご要望とか利用者の要望で、指導の時間を多く取るとか、そういったことは考えられるのか尋ねました。","respondent":"原交通安全担当課長","answer":"そういった事故の危険性の高いところは、交差点に限らずそういった要望等の声を反映させながら、柔軟に指導員を運用しております。そういった状況についても適宜、警察とも情報共有をしています。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"去年の年末ぐらいから４月過ぎても、道路管理者として、いわゆる無事故で生活できるような環境をまた進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"赤切符という形になってきたわけですから、今回、自転車の青切符ということです。お金が徴収されるわけですから、この辺は行政および警察は、もっとしっかり告知をしていかないといけないと思うのです。","respondent":"原交通安全担当課長","answer":"引き続き区で運用している指導員と、あと警察のほうで連携をして、広く周知をこれからもしていきたいと考えています。警察とも共有して、自転車指導員の運用も見直すなどして対応して、交通安全を実現できるように活動してまいりたいと考えています。","id":"exchange-016"},{"speaker":"藤原委員","kind":"質問・要望","question":"違反をすれば反則金という形で出るわけですから、この制度を担保していくというか、していっていただきたいという気持ちなのです。区民の方に丁寧、そして優しく分かりやすく説明していっていただきたいと思うのですけれども、最後にその辺はいかがか尋ねました。","respondent":"原交通安全担当課長","answer":"やはり交通事故を減らすという目的で導入された制度であると認識しておりますので、一番いいやり方を考えながら、丁寧にこれからも継続してまいりたいと思います。","id":"exchange-017"},{"speaker":"藤原委員","kind":"質問・要望","question":"義務を果たしていくという意味ですから、道路交通法を含めて大事なので、マナーの上の段階だと私は思っております。青切符制度も導入されたわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-02","title":"および⑵の陳情２件につきまして、関連する内容のため一括して議題に供します。 進め方として、２件の陳情","agenda":"および⑵の陳情２件につきまして、関連する内容のため一括して議題に供します。 進め方として、２件の陳情","exchanges":[{"speaker":"のだて委員","kind":"意見","question":"質疑の前に住民の皆さんが意見陳述されたいということですので、ぜひ住民の皆さんの話を聞いて、 それを基に質疑をしていくことが審議を深めていくことになると思いますので、先に意見陳述してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"区でできる支援があったら教えてほしいと言った思いを伺いたいのと、あとその後にも、このしなバスとの調整とは何なのか伺いたいと思います。その後、京急バスとは廃止以降、話合いなどはされているのか伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"一部でありますが、５月 １５日から運用開始したところでございまして、その調整を図っていたところです。実は５月にも一度、今後も継続的に、区民の皆さんのお声を届けていきたいという姿勢ではあります。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"区としても切実な思いだということは認識されているということで、移動手段の確保をすべきだと伺ったので伺いたいのと、あと５月に京急バスの本社に申入れに行かれたということで、そこではどういったことを求めたのか伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"５月の申入れにつきましては、状況の確認と、改めて継続的に再検討していただきたいということを申し述べさせていただきました。それが一定、交通ネットワークを整理していく観点の中で総合的にそれぞれの地区に対してどういうことができるかを考えていきたいと考えています。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間の質疑の中で、区民へのアンケートもやるというような答弁がありますけれども、それはいつ頃やる計画なのか伺いたいと思います。新たなところへ今、踏み出すべきではないかと思いますけれども、いかがか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"総合的に検討していくタイミングですが、品川区地域公共交通基本方針の中で、今年の下半期には大崎が始まるということを予定しております。適切なタイミングで実施して、区民の皆様と共に議論しながら、計画なり方針改定を行っていければよいのかなと考えています。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"一義的には、国や都が積極的に支援していくべきだと思いますけれども、それも区として求めてほしいと求めましたが、いかがでしょうか。やはりこうした支援に区としても踏み出して、公共交通であるバス交通を充実させていくことが必要だと思いますけれども、いかがか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"大田区、または品川区に関連する運転士のみを対象として支援することは、他区との公平性や補助効果の検証にも若干課題があると捉えております。一定、広域的な都の支援が充実してきたところですので、まずはそちらの状況を注視させていただければと考えています。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"改めて伺いたいのと、やはり重要なのが、区民の移動権を保障することだと思います。交通権の視点から、セーフティーネットとして公共交通の整備を進めていくことが必要だと思いますけれども、いかがか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"事業者からは、ない袖は振れないというような状況ということで、なかなかそういう資金的な部分というよりはというお話をいただいたところです。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"交通権の保障というところでも伺ったので、ぜひ交通権を保障する立場で取組を進めてほしいと求めましたが、いかがでしょうか。区内の公共交通、バス路線を守っていくことにもなるのではないかと思いますが、いかがか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"移動権、交通権と俎上にはあがっているところですが、明確に移動権という形では定義されているところに至っているものではないという認識です。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"やってほしいと求めましたし、大井町まで歩くと約３０分ぐらいかかるということで、東大井・南大井から大井町への交通手段を確保していただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"それ以外の地元の方も同様の要望をされていて、やはり同様の復活をという声を直接伺いましたので、これも併せてお伝えさせてほしいと求めました。ゼロとは言わないまでも、相当復活していると思うのですけれど、この部分はどう捉えていらっしゃるのかお伺いしたいと思います。","respondent":"櫻木地域交通政策課長","answer":"通勤需要等が全然戻ってきていないというような言い方をしていらっしゃったところですので、その意味では、戻り切っていないというのがこういう記述になっているのかなと考えています。","id":"exchange-027"},{"speaker":"田中委員","kind":"確認","question":"まず一つは、廃止することに伴って多大なる地域住民の方へ悪い影響を及ぼしてしまったことに対する何か言葉というのはなかったのでしょうか。確認したいと思います。","respondent":"櫻木地域交通政策課長","answer":"事業継続上、やはりやむを得ない判断ということで、会社として身を切るような思いでやったというようなお話はいただきました。京急バスとしましては、それを大井町の乗り入れを失うことについては、京急バスとしても非常に苦しい決断であったというような話は聞いております。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"そこからどうなるのか分かりませんけれども、私はぜひしなバスの運営として積極的に検討してほしいと求めましたが、いかがでしょうか。新たな鮫洲方面の方々が大井町に行くルートも併せて検討していただきたいのですが、まず具体的に実行できそうなものとしては、いかがか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"委員が今お話しされたように、京急バスが廃止されたことによって、一つの要因としてのそういう調整の懸念は軽減したという認識でいます。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひそれをお願いしたいのと併せて、ここでいう東大井方面地区の方の利便性向上に向けても、ぜひ引き続きご対応してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"松永委員","kind":"質問・要望","question":"先ほどの質疑の中でのことで伺いたいと思うのですが、区民アンケートの内容を作成していかれるのかお知らせほしいと求めました。２点目については、大井町の京急のバス停がなくなってしまったということを伺ったのですけれども、今現在どういった状況になっているのか。","respondent":"櫻木地域交通政策課長","answer":"専門家のご意見を聞きながら調査設計をするような認識でおりまして、侃々諤々議論しながらやっていくという意味で申し上げたところです。","id":"exchange-031"},{"speaker":"松永委員","kind":"質問・要望","question":"空白地帯とかいろいろあるとは思うのですけども、この陳情についての内容も含まれるのかどうかを伺いたいので、改めてお答えほしいと求めました。大井町のバス停について伺ったのですけれども、そうした要望があったらぜひともご意見を酌んでいただいて、。","respondent":"櫻木地域交通政策課長","answer":"アンケートについてですが、前回につきましては、無作為抽出で３,０００世帯にアンケー トをして、区全体の方々から意見を募っているところです。当然、そこで様々なご意見等も聴取して、会議体等でもんでいく形が想定されるのかなと考えています。","id":"exchange-032"},{"speaker":"松永委員","kind":"意見","question":"早急にこの路線バスを復活してほしい、また何らかの形で行動を示してほしいということなので、今後しっかりと頑張っていただければと。私たちも頑張っていきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問・要望","question":"一つお伺いしたいのは、京急に対して５月にも要望なのか、品川区がいろいろなお願いなり要望なりをするのは。あるいはそういうレベルによって口頭であったり、文書であったりとかというのがあったりするのかという、その辺の実状を教えていただきたいのですが。","respondent":"櫻木地域交通政策課長","answer":"定期的に１か月に１回、２回、密にコミュニケー ションを取らせていただいているところです。申入れの方法につきましては、口頭であったり、または文書という形で渡したりということは、その都度その状況に応じて変えているところです。","id":"exchange-034"},{"speaker":"塚本委員","kind":"質問","question":"今、大体分かりました。文書とかでやった場合は、返答みたいなものが来るのかどうなのか、どんな形で一応これまでは文書とか口頭とか返事が来ているのかを説明するよう求めました。","respondent":"櫻木地域交通政策課長","answer":"文書で回答が来ることはなくて、その場で、「承りました」とか「持ち帰らせていただきます」みたいな形で終わることが多いです。意見交換と、区としてはやはり看過できない状況ですので、改めてここで正式に再検討を申し上げますというような形でやっているような状況です。","id":"exchange-035"},{"speaker":"こしば委員","kind":"提案","question":"先ほど来の質疑をお聞きしまして思ったのは、交渉に臨んでほしいと求めましたし、ぜひ進めていってもらいたいものと思います。私もしなバスを、そういった提案もさせてもらったところではありましたけれども、課題はどういうところに出てくるのか教えてほしいと求めました。","respondent":"櫻木地域交通政策課長","answer":"課題という意味では、やはり東急バス自体も営業路線を既に減便しているということで、体力がないというところが最も大きな課題かなと考えています。","id":"exchange-036"},{"speaker":"こしば委員","kind":"質問・要望","question":"５００メートル以内なのかどうか。京急バスの路線の廃止の復活と、ほかの交通機関のほうの検討は、速やかに行ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"松永委員","kind":"質問・要望","question":"本陳情が抱える課題や地域の現状、今後の方向性について、十分理解ができたと考えています。つきまして、この意見陳述につきましては、なしとさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"のだて委員","kind":"意見","question":"ぜひ、住民の皆さんの声を聞いていきたいと。意見陳述をやるべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"松永委員","kind":"意見","question":"理由といたしましては、事業者側の運転手不足という事情は理解できるものの、区民の移動の足を守るためには様々な方法があると考えております。第１９号につきましては、今回、陳情第１９号につきましては採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"塚本委員","kind":"質問","question":"本日結論を出すで、結論は採択でお願いしたいと思います。まず民間バスについて、しっかりできるサービスの提供をお願いしていくことは大事だと思いますので、採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"松永委員","kind":"意見","question":"それを実現するための手法については検討すべき課題が多くありまして、コミュニティバスの拡大、様々あります。さらなる議論が必要だと考えておりますので、今回の陳情については、趣旨採択でとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"こしば委員","kind":"質問・要望","question":"そういう中で、 先ほどは京急バスの路線廃止の復活を求めることを、区のほうからもこれからも継続してやっていくという声もありました。総合的な視野を持って、この交通の利便性の向上を考えていくべきだと考え、継続とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"松永委員","kind":"意見","question":"今後また議論を深めていくということでございましたので、趣旨採択でなく、継続でお願いしたいと思います。大変失礼いたしましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"塚本委員","kind":"意見","question":"東京都のほうでは、 やはり同じように中間まとめというところでは、サービス水準をどう維持していくレベルを考えていくのか。地域でこうしてほしいというのは、継続した審議が必要かと思いますので、継続でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問・要望","question":"こちらは、京急バスの復活にとどまらずに、大井町への交通手段確保を求めるというもので、まさに住民の求めるものだと思います。やはりいろいろな手段がある中で、大井町への交通手段を確保してほしいというものだと思いますので、外出しなくなったという声もあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.07.02ma.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":29,"characters":35602,"voices":114}},{"id":"r08-20260708-10","meetingId":"r08-2t","date":"2026年7月8日","dateIso":"2026-07-08","committee":"議会運営委員会","time":"午前10時30分～午前10時47分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"予算要望なのですけれども、リーダー中心にと思っているのですけれども、いかがか尋ねました。","respondent":"渡辺議長","answer":"今、とても貴重なご発言、ご提案をいただいたので、事務局とも前向きに検討していきたいと思います。この会議体ではそう考えられるとか、そのような具体的なご提案は大歓迎だと思うので、よろしくお願いします。","id":"exchange-001"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.07.08gu.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":9,"characters":6598,"voices":35}}]);
